  Activity_116470_ActivityPlot = {
    Text = "নির্ধারিত পথের শেষ প্রান্তে, তারা আবারও একে অন্যকে হারিয়ে ফেলল।\nঘড়ি আবার টিকটিক শুরু করল, কিন্তু তখন অনেক দেরি হয়ে গেছে।\nসে একা রয়ে গেল, তার পবিত্র হৃদয় অনুতাপে রক্তাক্ত, আর সে শপথ করল অন্ধকারে পচে ওঠা সব কলুষতা শুদ্ধ করে ফেলবে।"
  },
  Activity_116470_ActivityStageEndContent = {
