  Activity_116765_ActivityName = {
    Text = "খোদিত যাত্রারম্ভ"
  },
  Activity_116765_ActivityTips = {
    Text = "ইভেন্ট নিয়মাবলী:\n1、গোপনরক্ষক নির্ধারিত যাত্রাপথ মিশন সম্পন্ন করার পর,「খোদিত যাত্রারম্ভ」-এ পুরস্কার সংগ্রহ করতে পারবেন।\n2、「প্রিমিয়াম যাত্রাপথ」আনলক করার পর, মিশন সম্পন্ন করলে অতিরিক্ত পুরস্কার সংগ্রহ করা যাবে।\n3、এবারের「প্রিমিয়াম যাত্রাপথ」ক্রয়ের সময়সীমা রয়েছে, মেয়াদ উত্তীর্ণ হলে আর ক্রয় করা যাবে না। অনুগ্রহ করে গোপনরক্ষক 3 নভেম্বর 9:00-এর আগে বিবেচনা করে ক্রয় করুন।\n4、অনুগ্রহ করে মনে রাখবেন: এই ইভেন্টে আনলক করা「প্রিমিয়াম যাত্রাপথ」শুধুমাত্র এই ইভেন্টে কার্যকর। অনুগ্রহ করে গোপনরক্ষক বিবেচনা করে যুক্তিসঙ্গতভাবে ব্যয় করুন।"
