  Activity_116818_ActivityPlot = {
    Text = "「তারকামণ্ডলী」 হলো তাঁর চোখ, তাঁর পক্ষ থেকে পর্যবেক্ষণ করে, অথবা বলা যায় জগতের সবকিছুর উপর নজরদারি করে।\nতুমি ভেবেছিলে তাঁর দৃষ্টি থেকে পালিয়েছ, কিন্তু সত্য হলো — তুমি এখনো তাঁর স্বপ্নের মধ্যেই আছ।\n「তোমাকে ধরে ফেলেছি —」\nতোমাকে বন্দী করার মুহূর্তে, তারকামণ্ডলী তৃপ্তির দীর্ঘশ্বাস ফেলল।"
  },
  Activity_116818_ActivityStageEndContent = {
    Text = "ইভেন্টটি সমাপ্ত হয়েছে।"
  },
  Activity_116818_ActivityTips = {
    Text = "<Title: আদি যুদ্ধে পুনরায়>\n·「আদি যুদ্ধে পুনরায়」 তে 7টি অপুনরাবৃত্তিযোগ্য স্টেজ রয়েছে যেখানে সরাসরি প্রাইমোর্ডিয়াল গেজের বিরুদ্ধে চ্যালেঞ্জ করা যাবে। ইভেন্টের প্রথম দুই দিনে 1টি, তৃতীয় দিনে 3টি এবং পরবর্তী দুই দিনে প্রতিদিন 1টি করে উন্মুক্ত হবে।\n·প্রতিটি চ্যালেঞ্জে সংশ্লিষ্ট স্টেলার প্রাইমোর্ডিয়াল গেজকে পরাজিত করলে সংশ্লিষ্ট পুরস্কার পাওয়া যাবে।\n·প্রতিটি ধরনের স্টেলার প্রাইমোর্ডিয়াল গেজের বিপুল সংখ্যক প্রতিরূপ রয়েছে। যখনই কোনো সিক্রেটকিপার কোনো নির্দিষ্ট ধরনের স্টেলার প্রাইমোর্ডিয়াল গেজকে পরাজিত করবে, সেই ধরনের 「অবশিষ্ট সংখ্যা」 1 কমে যাবে। যখন সেই ধরনের স্টেলার প্রাইমোর্ডিয়াল গেজ নির্মূল হবে, সংশ্লিষ্ট স্টেজ বন্ধ হয়ে যাবে এবং আর চ্যালেঞ্জ করা যাবে না।\n·প্রতিটি স্টেজ বিভিন্ন ক্রিয়েচার প্রদান করবে যা আপনাকে শক্তিশালী বোনাস দেবে।\n·সকল স্টেজে সহায়ক নির্বাচন করতে হবে। পুরো ইভেন্ট জুড়ে, প্রতিটি পারস্পরিক অনুসরণকারী সিক্রেটকিপার আপনাকে শুধুমাত্র একবার সহায়তা প্রদান করতে পারবে। সহায়ক ব্যবহারের কারণে, প্রকৃত সিঙ্ক্রো রেট পুরস্কার বেস পুরস্কারের উপর অতিরিক্ত 50% বৃদ্ধি পাবে।\n·প্রতিদিন প্রতিটি অ্যাওয়েকেনড, ফেট হুইল এবং কী সিগিল শুধুমাত্র 1 বার যুদ্ধে অংশ নিতে পারবে।\n·ইভেন্ট চলাকালীন স্পেশাল ডিসপ্যাচ রেকর্ড 「তারকামণ্ডলীর আরিয়া」 বিনামূল্যে আনলক হবে এবং কোনো পূর্বশর্ত প্রয়োজন নেই! গেমপ্লে ইভেন্ট 「আদি যুদ্ধে পুনরায়」 শেষ হওয়ার পর, স্পেশাল ডিসপ্যাচ রেকর্ড 「তারকামণ্ডলীর আরিয়া」 খুলতে প্রথমে 「তদন্ত অভিযান-তারকা অধ্যায়-চতুর্থ পর্ব」 সম্পন্ন করতে হবে।\n\n<Title: লেভেল ক্ষতিপূরণ>\n·「আদি যুদ্ধে পুনরায়」 তে লেভেল ক্ষতিপূরণ ব্যবস্থা রয়েছে, যাতে সকল সিক্রেটকিপার কাঁধে কাঁধ মিলিয়ে লড়তে পারে!\nলেভেল ক্ষতিপূরণের নিয়ম নিম্নরূপ:\n ·তদন্ত দলে, 60 লেভেলের নিচের অ্যাওয়েকেনডদের এই চ্যালেঞ্জে 60 লেভেলে ক্ষতিপূরণ দেওয়া হবে।\n ·তদন্ত দলে, 5 লেভেলের নিচের স্কিল লেভেলের অ্যাওয়েকেনডদের এই চ্যালেঞ্জে 5 লেভেলে ক্ষতিপূরণ দেওয়া হবে।\n ·তদন্ত দলে, 「উন্মাদনার পূর্বাভাস」 6 লেভেলের নিচের অ্যাওয়েকেনডদের এই চ্যালেঞ্জে 6 লেভেলে ক্ষতিপূরণ দেওয়া হবে।\n ·তদন্ত দলে, 「স্পিরিট শেপিং অ্যাপটিটিউড」 5 লেভেলের নিচের অ্যাওয়েকেনডদের এই চ্যালেঞ্জে 5 লেভেলে ক্ষতিপূরণ দেওয়া হবে।\n ·যদি সিক্রেটকিপারের লেভেল 60-এর নিচে হয়, এই চ্যালেঞ্জে 60 লেভেলে ক্ষতিপূরণ দেওয়া হবে।\n\n<Title:স্পেশাল ডিসপ্যাচ রেকর্ড>\n·ইভেন্ট চলাকালীন, 「স্পেশাল ডিসপ্যাচ রেকর্ড: তারকামণ্ডলীর আরিয়া」 বিনামূল্যে আনলক করা যাবে এবং কোনো পূর্বশর্ত প্রয়োজন নেই!\n·ইভেন্ট শেষ হওয়ার পর, 「স্পেশাল ডিসপ্যাচ রেকর্ড: তারকামণ্ডলীর আরিয়া」-এর তদন্ত অগ্রগতি সংরক্ষিত থাকবে। ইভেন্ট চলাকালীন অসম্পূর্ণ তদন্ত ইভেন্ট সম্পন্ন করলেও ইভেন্টের সময়কার একই তদন্ত পুরস্কার পাওয়া যাবে। যদি ইভেন্ট চলাকালীন 「স্পেশাল ডিসপ্যাচ রেকর্ড: তারকামণ্ডলীর আরিয়া」 আনলক না করা হয়, ইভেন্ট শেষ হওয়ার পর প্রথমে 「তদন্ত অভিযান-তারকা অধ্যায়-চতুর্থ পর্ব」 সম্পন্ন করতে হবে এবং 「রিয়ালিটি অরিজিন」 ×7 খরচ করে স্পেশাল ডিসপ্যাচ রেকর্ড 「তারকামণ্ডলীর আরিয়া」 খুলতে হবে।\n·ইভেন্ট চলাকালীন হোক বা না হোক, 「স্পেশাল ডিসপ্যাচ রেকর্ড: তারকামণ্ডলীর আরিয়া」 ক্লিয়ার করলে 「কী সিগিল: পুনর্মিলনের কামনা」 পাওয়া যাবে।"
