  Activity_119694_ActivityTips = {
    Text = "<Title:ইভেন্টের নিয়ম>\n·গোপনরক্ষক নির্দিষ্ট যাত্রা মিশন সম্পন্ন করার পর, 「প্রভাততারার পথনির্দেশ」 থেকে পুরস্কার সংগ্রহ করতে পারবেন।\n·「উন্নত যাত্রাপত্র」 আনলক করার পর, মিশন সম্পন্ন করলে অতিরিক্ত পুরস্কার সংগ্রহ করা যাবে।\n·এবারের 「উন্নত যাত্রাপত্র」 কেনার সময়সীমা আছে, মেয়াদ উত্তীর্ণ হলে আর কেনা যাবে না। গোপনরক্ষকদের অনুরোধ করা হচ্ছে 26 জানুয়ারি সকাল 9:00 (GMT+8)-এর আগে বিবেচনা করে কিনুন।\n·দয়া করে মনে রাখবেন: এই ইভেন্টে আনলক করা 「উন্নত যাত্রাপত্র」 শুধুমাত্র এই ইভেন্টে কার্যকর। গোপনরক্ষকদের বিবেচনাপূর্ণ ও যুক্তিসঙ্গত ব্যয় করার অনুরোধ করা হচ্ছে।"
