  Activity_119857_ActivityTips = {
    Text = "<Title:ইভেন্টের নিয়ম>\n·「নিদ্রিত প্রভু」ইভেন্ট চলাকালীন, গোপনরক্ষক তুলু অন্তর্ভুক্ত সিস্টেম প্রিসেট দল ব্যবহার করে নির্দিষ্ট স্টেজ সীমাহীনবার অভিজ্ঞতা করতে পারবেন।\n·ইভেন্ট স্টেজ অভিজ্ঞতার সময়, দলের জাগ্রত সত্তা পরিবর্তন করা যাবে না।\n<Title:ইভেন্ট পুরস্কার>\n·প্রথমবার স্টেজ চ্যালেঞ্জ সম্পন্ন করার পর, ইভেন্ট ইন্টারফেসে ট্রায়াল পুরস্কার সংগ্রহ করা যাবে।"
