  Activity_122195_ActivityPlot = {
    Text = "ভোরের আলো ধার্মিকের দুঃখকে দ্রবীভূত করে, আর নক্ষত্রেরা পাত্র হয়ে ওঠে, ভ্রাতা ও ভগ্নীদের বহন করে নিয়ে যায় মহিমান্বিত রাজ্যে।\nহারিয়ে যাওয়া মেষশাবক নৃত্য করে, গান গায় ফটকের সামনে, অনন্ত দেবসভায় তারার-দীপে সজ্জিত হয়ে।\nকিন্তু দরজার আড়ালের কুয়াশা বহু আগেই আহ্বানে সাড়া দিয়ে চলে এসেছে; এই কুয়াশা প্রতারণা করে, ছলনা করে, কেবল নিজের বিকৃত খেয়াল মেটানোর জন্য।\nতাই সে 「ভোর」-কে সিলমোহর করে, মুক্তিদানের পথ রুদ্ধ করে দেয়।\nএখানে, সে আরেকটি বিশ্বের অবসান প্রত্যক্ষ করবে।"
  },
  Activity_122195_ActivityStageEndContent = {
