  Activity_124051_ActivityPlot = {
    Text = "গভীর সাগরের প্রতিবিম্বে তার রাজার স্বপ্ন বিলীন হয়, আর দিব্য রাজ্য পচে ঝরে পড়ে।\nসে প্রাচীন স্বপ্নের অতল থেকে উদ্ভাসন হয়ে উঠে, ভেঙে পড়া ভবিষ্যতের ধ্বংসস্তূপে পা রাখে।\nসে অতলকে জিজ্ঞাসা করে, কিন্তু অতল নীরব থাকে।\nসে অতলকে উৎসর্গ অর্পণ করে, আর প্রতিধ্বনিতে কেবল নিজেরই কণ্ঠস্বর শোনে।"
  },
  Activity_124051_ActivityStageEndContent = {
    Text = "ইভেন্ট শেষ হয়েছে, বর্তমানে শুধুমাত্র 「গভীর অতলের প্রতিধ্বনি」-তে অংশগ্রহণ করা যাবে"
  },
  Activity_124051_ActivityTips = {
    Text = "<Title:ইভেন্ট সারসংক্ষেপ>\n1. ইভেন্ট চলাকালীন, কিপাররা সীমিত-সময়ের গেমপ্লে 「দিব্য পুনর্জন্ম「, 「দেবরাজের পবিত্র আদেশ「 এবং 「অর্জন পুরস্কার「 থেকে ইভেন্ট মুদ্রা সংগ্রহ করতে পারবেন। এই ইভেন্ট মুদ্রা 「অতলের প্রতিক্রিয়া「-তে উৎসর্গের জন্য ব্যবহার করে আইটেম পুরস্কার পাওয়া যাবে, যার মধ্যে রয়েছে সীমিত-সময়ের SR নিয়তিচক্র 「গভীর সাগরের ডাক「, এথেরিক স্টোন, পিওর কোর, লুমিনাস কোর এবং আরও অনেক কিছু।\n2. ইভেন্ট চলাকালীন 「ড্রিমস্কেপ: ডিজেক্রেট「 বিনামূল্যে উপলব্ধ থাকবে। ইভেন্ট অর্জন সম্পন্ন করলে সীমিত-সময়ের অবতার 「রৌপ্য চাবির নামে: মিরিয়াম「ও পাওয়া যাবে!\n\n<Title:ইভেন্ট সময়>\n1. 9 মার্চ 9:00 - 23 মার্চ 9:00 (GMT+8), সব ইভেন্ট কনটেন্টে অংশ নেওয়া যাবে।\n2. 23 মার্চ 9:00 - 30 মার্চ 9:00 (GMT+8), কেবল 「অতলের প্রতিক্রিয়া「 এবং 「অর্জন পুরস্কার「 থাকবে, অন্যান্য কনটেন্ট শেষ হয়ে যাবে এবং তাতে আর অংশ নেওয়া যাবে না।\n\n<Title:দিব্য পুনর্জন্ম>\n1. 「দিব্য পুনর্জন্ম「-এ 5টি স্তর রয়েছে, প্রতি 2 দিন পরপর স্বয়ংক্রিয়ভাবে 1টি করে স্তর খুলবে।\n2. প্রতিটি চ্যালেঞ্জে 120 মেনোফিন খরচ হবে, এবং সফল চ্যালেঞ্জে ইভেন্ট মুদ্রা পুরস্কার হিসেবে পাওয়া যাবে।\n3. কোনো স্তর সম্পন্ন করার পর, সেই স্তরের জন্য 「রিএন্যাক্ট「 ফিচার আনলক হবে। অনুগ্রহ করে লক্ষ করুন: 「রিএন্যাক্ট「 ব্যবহার করলে অ্যাফিনিটি পাওয়া যাবে না।\n4. আপনি অ্যালামনাই অ্যাসোসিয়েশন সাপোর্ট এবং 「রিচুয়াল: অ্যাবিসাল অফারিং「 ব্যবহার করে স্তরগুলো আরও সহজে সম্পন্ন করতে পারবেন।\n\n<Title:উৎসর্গ বোনাস>\n1. নির্দিষ্ট অ্যাওয়েকনার বা নিয়তিচক্রের মালিক কিপাররা (লাইনআপে থাকা আবশ্যক নয়) 「দিব্য পুনর্জন্ম「 স্তর টাস্কের পুরস্কারে (রিএন্যাক্টসহ) 「উৎসর্গকারীর অশ্রু「, 「উৎসর্গকারীর রক্ত「 এবং 「উৎসর্গকারীর মজ্জা「-র অতিরিক্ত ড্রপ বোনাস পাবেন, নিম্নরূপ:\nঅ্যাওয়েকনার 「মিরিয়াম「: এনলাইটেন 0/1/2/3 এবং তদূর্ধ্ব, বোনাস 20%/30%/40%/50%\nSSR নিয়তিচক্র 「ধার্মিকের মহাশক্তি「: অ্যাসেনশন 0/1/2/3 এবং তদূর্ধ্ব, বোনাস 20%/30%/40%/50%\nSR নিয়তিচক্র 「গভীর সাগরের ডাক「: অ্যাসেনশন 0/1/2/3 এবং তদূর্ধ্ব, বোনাস 20%/30%/40%/50%\n2. ভিন্ন অ্যাওয়েকনার বা নিয়তিচক্রের 「উৎসর্গ বোনাস「 যোগ করে গণনা করা হবে। \n3. উল্লেখযোগ্যভাবে, উন্মাদনা কঠিনতায় প্রথমবার সম্পন্ন করার চ্যালেঞ্জ পুরস্কার 「উৎসর্গ বোনাস「-এর প্রভাবমুক্ত থাকবে।\n\n<Title:রেজোন্যান্স: অ্যাবিসাল অফারিং>\n1. কিপাররা ইভেন্ট অর্জন সম্পন্ন করে 「নিষ্ঠার হৃদয়「 পেতে পারেন। \n2. 「নিষ্ঠার হৃদয়「 ব্যয় করে 「রেজোন্যান্স: অ্যাবিসাল অফারিং「 সক্রিয় করলে নিম্নলিখিত বোনাসগুলো পাওয়া যাবে:\n(1) ইভেন্ট গেমপ্লে 「দিব্য পুনর্জন্ম「-এ কিপারদের আরও শক্তিশালী করে, ফলে চ্যালেঞ্জ সহজ হয়।\n(2) 「দিব্য পুনর্জন্ম「 চ্যালেঞ্জ সম্পন্ন করার পর প্রাপ্ত ইভেন্ট মুদ্রার পরিমাণ বৃদ্ধি পায়।\n(3) ইভেন্ট গেমপ্লে 「দেবরাজের পবিত্র আদেশ「 সক্রিয় হয়।\n\n<Title:দেবরাজের পবিত্র আদেশ>\nরেজোন্যান্স 「উৎসর্গের পরীক্ষা「 সক্রিয় করার পর, আপনি প্রতি ঘন্টায় স্বয়ংক্রিয়ভাবে 60টি 「উৎসর্গকারীর অশ্রু「 পাবেন, সর্বোচ্চ 25 ঘন্টার সঞ্চয় পর্যন্ত।\n\n<Title:অতলের প্রতিক্রিয়া>\n1. 「অতলের প্রতিক্রিয়া「-তে তিনটি বেদি রয়েছে, যেগুলোর খোলার সময় নিম্নরূপ:\n「অশ্রুর বেদি「: 9 মার্চ 9:00 ~ 30 মার্চ 9:00।\n「রক্তের বেদি「: 11 মার্চ 9:00 ~ 30 মার্চ 9:00।\n「আত্মার বেদি「: 13 মার্চ 9:00 ~ 30 মার্চ 9:00।\n2. প্রতিটি উৎসর্গে 750 「উৎসর্গকারীর অশ্রু「/「উৎসর্গকারীর রক্ত「/「উৎসর্গকারীর মজ্জা「 খরচ হবে, এবং বেদি থেকে এলোমেলোভাবে পাঁচটি আইটেম পুরস্কার পাওয়া যাবে।\n3. প্রতিটি বেদির আইটেম পুরস্কার 「বিশেষ আইটেম「 এবং 「সাধারণ আইটেম「 হিসেবে ভাগ করা থাকে। রিসেট করার সময় নির্দিষ্ট আইটেম পুরস্কারের অবশিষ্ট পরিমাণ সীমা পর্যন্ত পুনরুদ্ধার করা যায়, নিয়মগুলো নিম্নরূপ:\n(1) প্রথম 3 বার রিসেট: যখন 「বিশেষ আইটেম「-এর অবশিষ্ট পরিমাণ শূন্য, কিপাররা রিসেট করতে পারেন, এতে 「বিশেষ আইটেম「 এবং 「সাধারণ আইটেম「 উভয়ের অবশিষ্ট পরিমাণই সর্বোচ্চ সীমায় ফিরে যাবে; তারা চাইলে উৎসর্গ চালিয়ে যেতে পারেন। যখন 「সাধারণ আইটেম「-এর অবশিষ্ট পরিমাণও শূন্য হয়ে যায়, তখন উৎসর্গ চালিয়ে যেতে রিসেট করা আবশ্যক।\n(2) চতুর্থ রিসেট থেকে পরবর্তী সব রিসেট: কেবল তখনই রিসেট করা যাবে যখন 「সাধারণ আইটেম「-এর অবশিষ্ট পরিমাণ শূন্য, এতে 「সাধারণ আইটেম「-এর অবশিষ্ট পরিমাণ সর্বোচ্চ সীমায় ফিরে যাবে, কিন্তু 「বিশেষ আইটেম「 আর রিসেট হবে না।\n\n<Title:ড্রিমস্কেপ>\n1. ইভেন্ট চলাকালীন 「ড্রিমস্কেপ: ডিজেক্রেট「 বিনামূল্যে উপলব্ধ থাকবে।\n2. ইভেন্ট শেষ হওয়ার পরও 「ড্রিমস্কেপ: ডিজেক্রেট「-এর তদন্ত অগ্রগতি সংরক্ষিত থাকবে। যদি ইভেন্ট চলাকালীন 「ড্রিমস্কেপ: ডিজেক্রেট「 আনলক না করা হয়ে থাকে, তবে ইভেন্টের পরও 「রিয়েলিটি ভার্জ「 *7 ব্যয় করে এটি আনলক করা যাবে।\n3. ইভেন্ট সময়কাল হোক বা না হোক, 「ড্রিমস্কেপ: ডিজেক্রেট「 সম্পন্ন করলে 「পসি: জোয়ারের উৎসব「 প্রদান করা হবে।\n\n<Title:রিরান ক্ষতিপূরণ>\n1. যারা পূর্বে 「ড্রিমস্কেপ: ডিজেক্রেট「 আনলক করেছেন, তারা এই রিরান ইভেন্টে পুনরায় আনলক করার সময় 「উৎসর্গকারীর অশ্রু「 *700 ক্ষতিপূরণ হিসেবে পাবেন।\n2. যারা পূর্বে সীমিত-সময়ের অবতার 「রৌপ্য চাবির নামে: মিরিয়াম「 পেয়েছেন, পুনরায় পাওয়ার সময় তা স্বয়ংক্রিয়ভাবে 「নিরাকারের আমন্ত্রণপত্র「 *1-এ রূপান্তরিত হবে।\n3. যারা পূর্বে রেজোন্যান্স সক্রিয়করণ উপাদান 「নিষ্ঠার হৃদয়「 পেয়েছেন, অতিরিক্ত প্রতিটি 「নিষ্ঠার হৃদয়「 স্বয়ংক্রিয়ভাবে 「রোজ স্ক্রিপ「 *5000-এ রূপান্তরিত হবে।\n"
