  Activity_124801_ActivityPlot = {
    Text = "আমি চাই সকলে বিশ্বজনীন তাস খেলুক!\nঅন্য এক টাইমলাইনের এক আগন্তুক ভুলবশত ট্রাফেজ স্থানে প্রবেশ করল, আর সেই স্থানকে তার পূর্ব রূপ থেকে সম্পূর্ণ ভিন্ন এক সত্তায় রূপান্তরিত করল।\nএই স্থানকে আবার উল্টে দিতে, ভিন্ন ভিন্ন টাইমলাইনের কিপারদের নির্ধারণ করতে হবে, তাদের মধ্যে কে সবচেয়ে শক্তিশালী, এবং সেই আগন্তুককে চ্যালেঞ্জ জানাতে হবে।"
