  Activity_126275_ActivityPlot = {
    Text = "চরকা আলতো করে ঘোরে, অনাদিকাল থেকে অবিরাম। সুতোর পথ ধরে নৃত্য করো, মহান বুনকর। ভাগ্য—এমন এক মঞ্চ যা থেকে তুমি কখনো পালাতে পারবে না।\nবিচারক। মুক্তিদাতা। প্রভু। বন্দী……\nএই মঞ্চে পা রাখার মুহূর্তেই, তোমার জন্য নির্ধারিত ভূমিকা বেছে নেওয়ার সুযোগ অনেক আগেই ফুরিয়ে গেছে।"
