  Activity_127173_ActivityTips = {
    Text = "<Title:ইভেন্ট নিয়মাবলী>\n·「চিত্রকর」ইভেন্ট চলাকালীন, গোপনরক্ষক পিকম্যান অন্তর্ভুক্ত সিস্টেম প্রিসেট দল ব্যবহার করে নির্দিষ্ট স্টেজ সীমাহীনবার অভিজ্ঞতা নিতে পারবেন।\n·ইভেন্ট স্টেজ অভিজ্ঞতার সময়, দলের জাগ্রত সত্তা পরিবর্তন করা যাবে না।\n<Title:ইভেন্ট পুরস্কার>\n·প্রথমবার স্টেজ চ্যালেঞ্জ সম্পন্ন করার পর, ইভেন্ট ইন্টারফেসে ট্রায়াল পুরস্কার সংগ্রহ করা যাবে।"
  },
  Activity_129488_ActivityName = {
    Text = "উন্মত্ত আকাশগামী রেল"
  },
  Activity_129488_ActivityPlot = {
    Text = "উন্মত্ত আদেশগুলো লাউঞ্জের নীরবতা বিদীর্ণ করে, ট্রেনের স্থির গুঞ্জনকে ডুবিয়ে দিল।\n「সালভাদোর, তৃতীয় কামরায় সহায়তা দরকার, প্লিজ!」\n「ওয়ান্ডা, তোমার নিয়ন্ত্রিত পুতুলগুলোকে পেছনে ঠেলে দাও; ওরা আমাদের গায়ে গা ঘেঁষে আসছে!」\n「রাইকার! ফ্লার্ট করা বন্ধ করো! আমার জানালার বাইরে যে বিকৃত জিনিসটা লেগে আছে, ওটাকে সরাতে এসে সাহায্য করো!」\nবিলাসবহুল কামরায়, তুমি এতটাই অভিভূত ছিলে যে খেয়ালই করোনি, এক ক্ষুদ্র অবয়ব নিঃশব্দে তোমার পকেটে গলে ঢুকে গেল।\n「হেহে, এখন থেকে আসল মজাটা শুরু হবে।」\n「টপ-টিয়ার ফুটেজ ধরে ফেলেছি~ এবার ছোট সহকারী 」এন「-এর মঞ্চে ওঠার পালা!」"
