  Activity_140082_ActivityPlot = {
    Text = "তারা তাদের চির-দহনশীল প্রভুর জন্য এক লিতানি গেয়ে ওঠে, এক কোরাস যা কখনো না-ভোলার অঙ্গীকার করে।\nসর্বোচ্চ স্বর্গ থেকে তিনি নেমে আসেন দ্যুতিময় আলোর ঝড়ে, তাঁর কণ্ঠ ঘোষণা করে অনন্ত গৌরব। যখন তাঁর পদধূলি পৃথিবীতে পড়বে, অ্যাম্বার আলো ঝরে পড়বে সমগ্র জগতে।\nএটাই সেই অন্ত্যেষ্টি, যা তিনি দান করেন।"
  },
  Activity_140082_ActivityStageEndContent = {
    Text = "ইভেন্ট শেষ হয়েছে, বর্তমানে শুধুমাত্র 「গোপন ঘাঁটি」-তে অংশগ্রহণ করা যাবে"
  },
  Activity_140082_ActivityTips = {
    Text = "<Title:কার্যক্রমের পরিচিতি>\n1、কার্যক্রম চলাকালীন, রক্ষকরা সীমিত সময়ের গেমপ্লে 「ভস্ম শিকার」、「নিরুপদ্রব ভোজ」 এবং 「অর্জন পুরস্কার」-এর মাধ্যমে কার্যক্রমের মুদ্রা 「সম্পদের 」মুদ্রা「」、「মৃত্যুর 」মুদ্রা「」、「যুদ্ধের 」মুদ্রা「」 সংগ্রহ করতে পারবেন। 「সম্পদের 」মুদ্রা「」、「মৃত্যুর 」মুদ্রা「」、「যুদ্ধের 」মুদ্রা「」 দিয়ে 「গোপন ঘাঁটি」-তে পণ্য কেনা যাবে, যার মধ্যে রয়েছে কার্যক্রমের সীমিত SR নিয়তিচক্র 「আসন্ন সূর্য」、লুমেন কোর、নির্মল মর্ম ইত্যাদি।\n2、কার্যক্রম চলাকালীন, 「অমর মেরুদিন」 সীমিত সময়ের জন্য বিনামূল্যে আনলক হবে, কার্যক্রমের অর্জন সম্পন্ন করলে কার্যক্রমের সীমিত অ্যাভাটার 「রৌপ্য চাবির নামে：ক্যাটিগুলা」 পাওয়া যাবে!\n\n<Title:কার্যক্রমের সময়>\n1、সেপ্টেম্বর 7 তারিখ 9:00 - অক্টোবর 5 তারিখ 9:00（GMT+8）, সমস্ত ইভেন্ট গেমপ্লেতে অংশগ্রহণ করা যাবে।\n2、অক্টোবর 5 তারিখ 9:00 - অক্টোবর 12 তারিখ 9:00（GMT+8）, শুধুমাত্র 「গোপন ঘাঁটি」 এবং অর্জন পুরস্কারে অংশগ্রহণ করা যাবে।\n\n<Title:ভস্ম শিকার>\n1、「ভস্ম শিকার」-এ 7টি স্তর রয়েছে, প্রতি 1 দিনে স্বয়ংক্রিয়ভাবে 1টি খুলবে।\n2、প্রতিটি চ্যালেঞ্জে 「মেনোফিন」× 120 খরচ হবে, চ্যালেঞ্জ সফল হলে কার্যক্রমের মুদ্রা পাওয়া যাবে।\n3、স্তর ক্লিয়ার করার পরে, সেই স্তরের 「পুনর্মঞ্চায়ন」 ফিচার আনলক হবে। অনুগ্রহ করে মনে রাখুন: 「পুনর্মঞ্চায়ন」 ফিচার ব্যবহার করার সময় সমসংস্থান হার পাওয়া যাবে না।\n4、তোমাকে আরও সহজে পার হতে সাহায্য করতে অ্যালামনাই অ্যাসোসিয়েশনের সহায়তা ব্যবহার করা যাবে।\n\n<Title: গোপন ঘাঁটি>\n「গোপন ঘাঁটি」-তে মোট তিনটি দোকান রয়েছে, খোলার সময় নিচে দেওয়া হলো：\n·「সংগ্রহের ভাণ্ডার」： সেপ্টেম্বর 7 তারিখ 9টায় খুলবে।\n·「কমিশন গোপন কক্ষ」： সেপ্টেম্বর 8 তারিখ 9টায় খুলবে।\n·「যুদ্ধ শিবির」： সেপ্টেম্বর 9 তারিখ 9টায় খুলবে।\nদোকানে পণ্য বেছে সরাসরি কেনা যাবে।\n\n<Title:কার্যক্রমের বোনাস>\n1、রক্ষকদের কাছে নির্দিষ্ট জাগরণকারী বা নিয়তিচক্র থাকলে（দলে রাখার প্রয়োজন নেই）「ভস্ম শিকার」 স্তরের কাজের পুরস্কারে 「সম্পদের 」মুদ্রা「」、「মৃত্যুর 」মুদ্রা「」、「যুদ্ধের 」মুদ্রা「」-এ অতিরিক্ত ড্রপ বোনাস পাওয়া যাবে, বিস্তারিত বোনাস নিচে দেওয়া হলো：\n·জাগরণকারী 「ক্যাটিগুলা」：আত্মজাগরণ 0/1/2/3 ও তার বেশি, বোনাস 20%/30%/40%/50%।\n·SSR নিয়তিচক্র 「অ্যাম্বার মৃত্যু」：ওভারল্যাপ 0/1/2/3 ও তার বেশি, বোনাস 20%/30%/40%/50%।\n·SR নিয়তিচক্র 「আসন্ন সূর্য」：ওভারল্যাপ 0/1/2/3 ও তার বেশি, বোনাস 20%/30%/40%/50%।\n2、বিভিন্ন জাগরণকারী বা নিয়তিচক্রের 「কার্যক্রমের বোনাস」 স্তুপাকারে যোগ হয়। \n3、বিশেষভাবে, উন্মাদ কঠিনতার প্রথমবার ক্লিয়ার চ্যালেঞ্জ পুরস্কার 「কার্যক্রমের বোনাস」 দ্বারা প্রভাবিত হবে না।\n\n<Title: নিরুপদ্রব ভোজ>\n1、প্রতি ঘণ্টায় স্বয়ংক্রিয়ভাবে 60 「সম্পদের 」মুদ্রা「」 পাওয়া যাবে, সর্বোচ্চ 25 ঘণ্টা সংরক্ষণ করা যাবে।\n\n<Title:চেতনার বিচরণ>\n1、কার্যক্রম চলাকালীন, 「অমর মেরুদিন」 বিনামূল্যে আনলক করা যাবে।\n2、কার্যক্রম শেষ হওয়ার পরে, 「অমর মেরুদিন」-এর তদন্তের অগ্রগতি ধরে রাখো হবে, কার্যক্রম চলাকালীন অসম্পূর্ণ ঘটনা তদন্ত সম্পন্ন করলেও কার্যক্রম চলাকালীনের মতো একই তদন্ত পুরস্কার পাওয়া যাবে। যদি কার্যক্রম চলাকালীন 「অমর মেরুদিন」 আনলক না করা হয়, কার্যক্রম শেষ হওয়ার পরেও 「বাস্তবতার সূচনাবিন্দু」×3 খরচ করে আনলক করা যাবে।\n3、কার্যক্রম চলাকালীন হোক বা না হোক, 「চেতনার বিচরণ：অমর মেরুদিন」 ক্লিয়ার করার পরে 「পসি：অস্তহীন সূর্য」 পাওয়া যাবে।"
