  Activity_141509_ActivityTips = {
    Text = "<Title:ইভেন্টের নিয়ম>\n1、রক্ষকরা নির্দিষ্ট নোটের কাজ সম্পন্ন করার পরে 「রহস্যময় ভ্রমণ বৃত্তান্ত」 এ পুরস্কার গ্রহণ করতে পারবেন।\n2、「রহস্যময় ভ্রমণ বৃত্তান্ত」 27 জুলাই 09:00 তে শেষ হবে।\n3、「উচ্চ পর্যায়ের যাত্রাবৃত্তান্ত」 আনলক করার পরে, কাজ সম্পন্ন করলে অতিরিক্ত পুরস্কার গ্রহণ করা যাবে।\n4、অনুগ্রহ করে মনে রাখুন: এই ইভেন্টে আনলক করা 「উচ্চ পর্যায়ের যাত্রাবৃত্তান্ত」 শুধুমাত্র এই ইভেন্টে কার্যকর। রক্ষকরা বিবেচনা করে যুক্তিসঙ্গতভাবে ব্যয় করুন।"
