  Activity_141533_ActivityPlot = {
    Text = "আসো আমরা উচ্চস্বরে হাসি, আসো আমরা সারারাত উৎসব করি।\nআসো আমাদের হুক-নখ শত্রুর গলা ভেদ করুক, আসো সাধারণ সময় গভীর অতলে মরিচা ধরুক।\nআমরা আর কখনো বার্ধক্য, সাধারণত্ব আর একাকীত্বের কবলে পড়ব না।\nএটি এপোয়ান্স, আমরা চিরকাল সুখী, আমরা চিরকাল একসাথে।\nআমরা কখনো বিচ্ছেদ হব না।"
