  Activity_145458_ActivityPlot = {
    Text = "লোভী বীর চেয়েছিল অমর সিংহাসন, হতাশ মাতা চেয়েছিল মৃত সন্তানের পুনর্জীবন, উন্মাদ জাদুকর চেয়েছিল নিষিদ্ধ জ্ঞান—— তারা তাঁর সামনে হাঁটু গেড়ে বসে, সেই পুরনো ভাষায় ভিক্ষা চাইল যা তিনি হাজার বছর ধরে শুনে আসছেন।\nতিনি তাদের সব দিলেন, তারপর দেখলেন তারা সব হারিয়ে ফেলল। তিনি চার হাজার ভয়াবহ প্রতিযোগিতা দেখেছেন, তবুও কখনো তৃপ্ত হননি।\nএবার, কলোসিয়ামের দ্বার তোমার জন্য উন্মুক্ত। এসো, তাঁকে বলো, তুমি কীসের জন্য আকুল।\nতাঁকে বলো, তুমি আর সেই চার হাজার মৃত আত্মার মধ্যে আসলে কী পার্থক্য।"
  },
  Activity_145458_ActivityStageEndContent = {
    Text = "ইভেন্ট শেষ হয়েছে, বর্তমানে শুধুমাত্র「অস্থায়ী টেক্সট」-এ অংশগ্রহণ করা যাবে"
  },
  Activity_145458_ActivityTips = {
    Text = "<Title:ইভেন্টের সংক্ষিপ্ত বিবরণ>\nইভেন্ট চলাকালীন, রক্ষকরা সীমিত সময়ের গেমপ্লে 「রক্তলোভী প্রতিযোগিতা」 এবং 「অর্জন পুরস্কার」 থেকে ইভেন্ট মুদ্রা 「রক্তিম বলি」 সংগ্রহ করতে পারবেন। 「রক্তিম বলি」 দিয়ে 「কলোসিয়াম বলিবেদি」-তে পুরস্কার বিনিময় করা যাবে, যার মধ্যে রয়েছে ইভেন্ট সীমিত SR নিয়তিচক্র 「অবিনশ্বর ক্ষুধার্ত অস্থি」, লুমেন কোর, নির্মল মর্ম, জ্ঞানপ্রস্তর খণ্ড, অনুকরণ স্ফটিক ইত্যাদি।\n\n<Title:রক্তলোভী প্রতিযোগিতা>\n1、「রক্তলোভী প্রতিযোগিতা」-তে ৫টি স্তর রয়েছে, প্রতি ২ দিনে স্বয়ংক্রিয়ভাবে ১টি উন্মুক্ত হয়।\n2、প্রতিটি চ্যালেঞ্জে 「মেনোফিন」× ১২০ খরচ হবে, চ্যালেঞ্জ সফল হলে ইভেন্ট মুদ্রা 「রক্তিম বলি」 পাওয়া যাবে।\n3、স্তর ক্লিয়ার করার পর, সেই স্তরের 「পুনর্মঞ্চায়ন」 ফিচার আনলক হবে। অনুগ্রহ করে মনে রাখবেন：「পুনর্মঞ্চায়ন」 ফিচার ব্যবহার করার সময় সমসংস্থান হার পাওয়া যাবে না।\n4、তোমাকে আরও সহজে ক্লিয়ার করতে সাহায্য করতে প্রাক্তন ছাত্র সংঘের সহায়তা যুদ্ধ ব্যবহার করা যাবে।\n\n<Title:ইভেন্ট বোনাস>\n1、রক্ষকদের কাছে নির্দিষ্ট জাগরণকারী বা নিয়তিচক্র থাকলে (দলে থাকার প্রয়োজন নেই) 「রক্তলোভী প্রতিযোগিতা」 স্তরের কাজের পুরস্কারে 「রক্তিম বলি」-এর অতিরিক্ত ড্রপ বোনাস পাওয়া যাবে (পুনর্মঞ্চায়নসহ), বিস্তারিত বোনাস নিচে দেওয়া হলো：\n·জাগরণকারী 「ক্ষয়·রোটান」：আত্মজাগরণ ০/১/২/৩ ও তার বেশিতে, বোনাস ২০%/৩০%/৪০%/৫০%\n·SSR নিয়তিচক্র 「আকাশের পতন」：ওভারল্যাপ ০/১/২/৩ ও তার বেশিতে, বোনাস ২০%/৩০%/৪০%/৫০%\n·SR নিয়তিচক্র 「অবিনশ্বর ক্ষুধার্ত অস্থি」：ওভারল্যাপ ০/১/২/৩ ও তার বেশিতে, বোনাস ২০%/৩০%/৪০%/৫০%\n2、বিভিন্ন জাগরণকারী বা নিয়তিচক্রের 「ইভেন্ট বোনাস」 স্তরযোগ পদ্ধতিতে গণনা করা হয়।\n3、বিশেষভাবে, উন্মাদ কঠিনতার প্রথম ক্লিয়ার চ্যালেঞ্জ পুরস্কার উপরোক্ত বোনাস দ্বারা প্রভাবিত হবে না।\n\n<Title:চেতনার বিচরণ>\n1、ইভেন্ট চলাকালীন, 「চেতনার বিচরণ：যতক্ষণ তিমি-আকাশ পতিত না হয়」 বিনামূল্যে আনলক করা যাবে।\n2、ইভেন্ট শেষ হওয়ার পরেও 「চেতনার বিচরণ：যতক্ষণ তিমি-আকাশ পতিত না হয়」-এর তদন্তের অগ্রগতি ধরে রাখো হবে, ইভেন্ট চলাকালীন অসম্পূর্ণ ঘটনা তদন্ত সম্পন্ন করলেও ইভেন্ট চলাকালীনের মতো একই তদন্ত পুরস্কার পাওয়া যাবে। ইভেন্ট চলাকালীন যদি 「চেতনার বিচরণ：যতক্ষণ তিমি-আকাশ পতিত না হয়」 আনলক না করা হয়, তাহলে ইভেন্ট শেষ হওয়ার পরেও 「বাস্তবতার সূচনাবিন্দু」×৩ খরচ করে আনলক করা যাবে।\n3、ইভেন্ট চলাকালীন হোক বা না হোক, 「চেতনার বিচরণ：যতক্ষণ তিমি-আকাশ পতিত না হয়」 ক্লিয়ার করার পর 「পসি：তিমি-গ্রাসী ঝড়」 পাওয়া যাবে।\n\n<Title:ইভেন্টের সময়সূচি>\n1、২৭ জুলাই ৯:০০ - ২৪ আগস্ট ৯:০০ (GMT+8), ইভেন্টের সংক্ষিপ্ত বিবরণে উল্লিখিত সমস্ত বিষয়বস্তুতে অংশগ্রহণ করা যাবে।\n2、২৪ আগস্ট ৯:০০ - ৩১ আগস্ট ৯:০০ (GMT+8), শুধুমাত্র 「কলোসিয়াম বলিবেদি」 এবং 「অর্জন পুরস্কার」 ধরে রাখো থাকবে, অন্যান্য বিষয়বস্তু সমাপ্ত হয়ে যাবে এবং অংশগ্রহণ করা যাবে না।\n3、৩১ আগস্ট ৯:০০ (GMT+8)-এর পরে, অবশিষ্ট অবিনিময়িত 「রক্তিম বলি」 প্রতিটির বিনিময়ে 「সোনালি গোলাপ」× ৪০ হারে পুনরুদ্ধার করা হবে, রক্ষকরা অনুগ্রহ করে মেইল চেক করুন।"
  },
