  Activity_23723_ActivityName = {
    Text = "ঝড় আসছে"
  },
  Activity_23723_ActivityTips = {
    Text = "ইভেন্ট নিয়মাবলী：\n1、ইভেন্ট চলাকালীন, তদন্ত অভিযানের পঞ্চম অধ্যায় সাময়িকভাবে বন্ধ থাকবে, কী-কমান্ড 「চিরন্তন আবেশ」 সাময়িকভাবে তদন্ত অভিযানের চতুর্থ অধ্যায় ক্লিয়ার করে পাওয়া যাবে।\n2、ইভেন্ট শেষ হওয়ার পর, তদন্ত অভিযানের পঞ্চম অধ্যায় পুনরায় খোলা হবে, কী-কমান্ড 「চিরন্তন আবেশ」 এখনও তদন্ত অভিযানের পঞ্চম অধ্যায় ক্লিয়ার করে পেতে হবে।\n3、এছাড়াও, পূর্বে অর্জিত পঞ্চম অধ্যায়ের অ্যাচিভমেন্ট পুরস্কার, স্টেজ অ্যাচিভমেন্ট পুরস্কার, অন্বেষণ পুরস্কার, ক্লিয়ার পুরস্কার সবই সংরক্ষিত থাকবে। পুনরায় খোলার সময় (বর্তমান পরিকল্পনা অনুযায়ী 12ই ডিসেম্বর 27 তারিখ), সংশ্লিষ্ট সম্পন্ন অগ্রগতি যতটা সম্ভব স্থানান্তরিত ও সংরক্ষিত থাকবে, পুনরায় সম্পন্ন করার প্রয়োজন নেই।"
  },
