  Activity_23953_ActivityPlot = {
    Text = "ইভেন্ট চলাকালীন, গোপনরক্ষক「স্বপ্ন গভীর ডুব」এবং「ফেজ দাবা」থেকে প্রাপ্ত গোপনরক্ষক অভিজ্ঞতা দ্বিগুণ হবে, দৈনিক সীমা 480 পয়েন্টে উন্নীত হবে।"
  },
  Activity_23953_ActivityTips = {
