  Activity_24194_ActivityTips = {
    Text = "<Title:ইভেন্টের নিয়ম>\n·「রেড লেডি」ইভেন্ট চলাকালীন, কিপার সোরেল অন্তর্ভুক্ত সিস্টেম প্রিসেট দল ব্যবহার করে নির্ধারিত স্টেজ সীমাহীনবার অভিজ্ঞতা করতে পারবেন।\n·ইভেন্ট স্টেজ অভিজ্ঞতার সময়, দলের অ্যাওয়েকেনার পরিবর্তন করা যাবে না।\n<Title:ইভেন্ট পুরস্কার>\n·প্রথমবার স্টেজ চ্যালেঞ্জ সম্পন্ন করার পর, ইভেন্ট ইন্টারফেসে ট্রায়াল পুরস্কার সংগ্রহ করা যাবে।"
  },
  Activity_24195_ActivityName = {
