  Activity_25011_ActivityPlot = {
    Text = "তুমি এক পা বাড়াও, আর পেরিয়ে যাও অন্য এক কাল ও পরিসরে।"
  },
  Activity_25011_ActivityTips = {
    Text = "<Title:অংশগ্রহণের শর্ত>\n·চেতনা অভিযান 「নাইটের ইচ্ছা」 সাধারণ মোড সম্পন্ন করার পর অংশগ্রহণ করা যাবে। \n<Title:তদন্ত ইভেন্ট>\n·ইভেন্ট চলাকালীন, প্রতিদিন 「এক পা দূরে」-এর একটি নতুন তদন্ত ইভেন্ট উন্মুক্ত হবে, গোপনরক্ষক কোনো সম্পদ খরচ না করেই তদন্ত আনলক ও পরিচালনা করতে পারবেন, তদন্ত ইভেন্ট সম্পন্ন করার পর নির্মল কোর, তদন্ত ব্যাজ এবং গোপনরক্ষক অভিজ্ঞতা ইত্যাদি তদন্ত পুরস্কার পাওয়া যাবে।\n·ইভেন্ট শেষ হওয়ার পর, 「এক পা দূরে」-এর তদন্ত অগ্রগতি সংরক্ষিত থাকবে, গোপনরক্ষক চেতনা অভিযানে ক্ষয়গোলক খরচ করে আনলক না হওয়া তদন্ত আনলক করতে পারবেন, ইভেন্ট চলাকালীন অসম্পূর্ণ তদন্ত ইভেন্ট সম্পন্ন করার পরও ইভেন্ট চলাকালীন সময়ের মতো একই তদন্ত পুরস্কার পাওয়া যাবে।<Title:সীমিত সময়ের পুরস্কার>\n·ইভেন্ট চলাকালীন সীমিত সময়ের পুরস্কার উন্মুক্ত হবে, গোপনরক্ষক 「এক পা দূরে」 সাধারণ মোড ক্লিয়ার এবং 「এক পা দূরে」-এর তদন্ত ইভেন্ট সম্পন্ন করার পর, লাকি ক্যান্ডি এবং সিলভার কোর পুরস্কার পেতে পারবেন! সীমিত সময়ের পুরস্কার শুধুমাত্র ইভেন্ট চলাকালীন উন্মুক্ত থাকবে, ইভেন্ট শেষ হওয়ার পর সম্পন্ন ও সংগ্রহ করা যাবে না।"
  },
  Activity_25011_UnlockConditionExplanation = {
