  Activity_25012_ActivityName = {
    Text = "গোলাপের প্রশস্তি"
  },
  Activity_25012_ActivityPlot = {
    Text = "ভদ্রমহিলা ও ভদ্রলোকগণ।\nস্নিগ্ধ রাত্রি তার পর্দা সরিয়ে নিয়েছে—প্রস্তুত করুন আপনার শ্রেষ্ঠ পানীয়।\nএ এক দীর্ঘ কাহিনি। অবকাশ নিয়ে আপনাদের তা শোনাতে দিন।"
  },
  Activity_25012_ActivityTips = {
    Text = "<Title:অংশগ্রহণের শর্তাবলি>\nঅংশগ্রহণ করতে 「তদন্ত অভিযান」 2-9(সাধারণ) সম্পন্ন করুন।\n<Title:তদন্ত ইভেন্ট>\nইভেন্ট চলাকালীন, প্রতিদিন 「গোলাপের প্রশস্তি」 থেকে একটি নতুন তদন্ত ইভেন্ট চালু হবে। রক্ষকেরা সামগ্রী ব্যয় না করেই এগুলো আনলক ও তদন্ত করতে পারবেন। তদন্ত ইভেন্ট সম্পন্ন করার পর নির্মল মর্ম, অনুসন্ধান ব্যাজ, এবং রক্ষক অভিজ্ঞতা ইত্যাদি পুরস্কার প্রাপ্ত হবে।\nইভেন্ট শেষ হওয়ার পরও 「গোলাপের প্রশস্তি」-এর তদন্ত অগ্রগতি ধরে রাখা হবে, এবং রক্ষকেরা বিশেষ অপসে ডি-জুয়েল ব্যয় করে অসম্পন্ন তদন্তগুলো আনলক করতে পারবেন। ইভেন্ট চলাকালীন অসম্পন্ন তদন্ত ইভেন্ট সম্পন্ন করলে, ইভেন্ট চলাকালীন প্রাপ্ত পুরস্কারের সঙ্গেই সামঞ্জস্যপূর্ণ পুরস্কার প্রদান করা হবে।<Title:সীমিত সময়ের পুরস্কার>\nইভেন্ট চলাকালীন সীমিত সময়ের পুরস্কার সংগ্রহযোগ্য থাকবে। রক্ষকেরা 「গোলাপের প্রশস্তি」(সাধারণ) মোড সম্পূর্ণ করে এবং 「গোলাপের প্রশস্তি」-এর তদন্ত ইভেন্টসমূহ শেষ করে নির্মল মর্ম, পরশমণি, এবং রৌপ্য অর্জন করতে পারবেন! সীমিত সময়ের পুরস্কার কেবল ইভেন্ট চলাকালীনই সংগ্রহযোগ্য, ইভেন্ট শেষ হওয়ার পর এগুলো আর সম্পন্ন বা দাবি করা যাবে না।"
  },
