  Activity_35844_ActivityName = {
    Text = "গভীর সমুদ্রের ভদ্রমহিলা"
  },
  Activity_35844_ActivityTips = {
    Text = "<Title:ইভেন্টের নিয়ম>\n·「গভীর সমুদ্রের ভদ্রমহিলা」ইভেন্ট চলাকালীন, কিপার মার্ফি অন্তর্ভুক্ত সিস্টেম প্রিসেট দল ব্যবহার করে নির্ধারিত স্টেজ সীমাহীনবার অভিজ্ঞতা করতে পারবেন।\n·ইভেন্ট স্টেজ অভিজ্ঞতার সময়, দলের অ্যাওয়েকেনার পরিবর্তন করা যাবে না।\n<Title:ইভেন্ট পুরস্কার>\n·প্রথমবার স্টেজ চ্যালেঞ্জ সম্পন্ন করার পর, ইভেন্ট ইন্টারফেসে ট্রায়াল পুরস্কার সংগ্রহ করা যাবে।"
  },
  Activity_35983_ActivityName = {
    Text = "একাডেমি উপহার"
  },
  Activity_35983_ActivityTips = {
    Text = "ইভেন্টের নিয়মাবলী：\n1、সিক্রেটকিপার প্রতিদিন লগইন করার পর 「একাডেমি উপহার」-এ সেদিনের সাইন-ইন পুরস্কার সংগ্রহ করতে পারবেন।\n2、পুরস্কার সিক্রেটকিপারের ক্রমিক লগইনের ভিত্তিতে ক্রমান্বয়ে আনলক হবে, সেদিনের সাইন-ইন পুরস্কার সকাল 9টায় (GMT+8) রিফ্রেশ হবে।"
  },
