  Activity_38716_ActivityTips = {
    Text = "<Title:ইভেন্ট পরিচিতি>\n·সিক্রেটকিপাররা 「প্রত্যাবর্তন পুরস্কার」 থেকে সরাসরি 「পুনরায় শুরুর সরবরাহ」 পুরস্কার সংগ্রহ করতে পারবে।\n·নির্দিষ্ট প্রশিক্ষণ মিশন সম্পন্ন করলে 「তদন্ত পুনরায় শুরু」 ইভেন্ট থেকে পুরস্কার সংগ্রহ করা যাবে।\n·সকল প্রশিক্ষণ মিশন সম্পন্ন করলে অতিরিক্ত পুরস্কারও পাওয়া যাবে।"
