  Activity_38805_ActivityPlot = {
    Text = "ইসারাউ, হ্রদের মধ্যে নগরী, কথিত আছে সেটিই ওয়ান্ডার শ্বেত পাখির দেশ।\nএইবার তুমি অতিক্রম করবে স্বপ্নলোকের দ্বার, পৌঁছে যাবে প্রাচীন মিনারে, যেখানে ঘড়ি-জিহ্বার ভিড়..."
