  Activity_43569_ActivityTips = {
    Text = "ইভেন্টের নিয়মাবলী：\n1、সিক্রেটকিপার নির্ধারিত ভ্রমণকথা মিশন সম্পন্ন করার পর, 「মহাসাগরীয় ভ্রমণকথা」-তে পুরস্কার সংগ্রহ করতে পারবেন।\n2、「মহাসাগরীয় ভ্রমণকথা」স্থায়ীভাবে উন্মুক্ত।\n3、「প্রিমিয়াম ভ্রমণকথা」আনলক করার পর, মিশন সম্পন্ন করলে অতিরিক্ত পুরস্কার সংগ্রহ করা যাবে।\n4、অনুগ্রহ করে মনে রাখবেন: এই ইভেন্টে আনলক করা 「প্রিমিয়াম ভ্রমণকথা」শুধুমাত্র এই ইভেন্টে কার্যকর। সিক্রেটকিপার অনুগ্রহ করে বিবেচনা করে যুক্তিসঙ্গতভাবে খরচ করুন।"
