  },
  Activity_43570_ActivityTips = {
    Text = "ইভেন্টের নিয়মাবলী：\n1、সিক্রেটকিপার নির্ধারিত ভ্রমণকথা মিশন সম্পন্ন করার পর, 「তুষার নগরীর ভ্রমণকথা」-তে পুরস্কার সংগ্রহ করতে পারবেন।\n2、「তুষার নগরীর ভ্রমণকথা」স্থায়ীভাবে উন্মুক্ত।\n3、「প্রিমিয়াম ভ্রমণকথা」আনলক করার পর, মিশন সম্পন্ন করলে অতিরিক্ত পুরস্কার সংগ্রহ করা যাবে।\n4、অনুগ্রহ করে মনে রাখবেন: এই ইভেন্টে আনলক করা 「প্রিমিয়াম ভ্রমণকথা」শুধুমাত্র এই ইভেন্টে কার্যকর। সিক্রেটকিপার অনুগ্রহ করে বিবেচনা করে যুক্তিসঙ্গতভাবে খরচ করুন।"
  },
  Activity_43572_ActivityName = {
    Text = "আলকেমি নন্দনতত্ত্ব"
  },
  Activity_43572_ActivityTips = {
    Text = "ইভেন্টের নিয়ম:\n1、「অ্যালকেমিক্যাল অ্যাসথেটিক্স」ইভেন্ট চলাকালীন, কিপার অফ সিক্রেটস「গোল্ড ভাউচার সার্চ」-এ অনুসন্ধান বা পুনরায় চ্যালেঞ্জ করলে অতিরিক্ত 100% পুরস্কার পাবেন (কিপার অফ সিক্রেটস অভিজ্ঞতা ব্যতীত), প্রতিদিন সর্বোচ্চ 6 বার।"
