  Activity_44716_ActivityTips = {
    Text = "<Title:ইভেন্টের নিয়ম>\n·「নিদ্রিত প্রভু」ইভেন্ট চলাকালীন, গোপনরক্ষক তুলু অন্তর্ভুক্ত সিস্টেম প্রিসেট দল ব্যবহার করে নির্দিষ্ট স্টেজ সীমাহীনবার অভিজ্ঞতা করতে পারবেন।\n·ইভেন্ট স্টেজ অভিজ্ঞতার সময়, দলের জাগ্রত সত্তা পরিবর্তন করা যাবে না।\n<Title:ইভেন্ট পুরস্কার>\n·প্রথমবার স্টেজ চ্যালেঞ্জ সম্পন্ন করার পর, ইভেন্ট ইন্টারফেসে ট্রায়াল পুরস্কার সংগ্রহ করা যাবে।"
  },
  Activity_45664_ActivityName = {
    Text = "দৈত্যের পতন"
  },
  Activity_45664_ActivityPlot = {
    Text = "অন্তহীন সমুদ্র, প্রখর সূর্য, নির্বাসিত ফিলিস্তিন বীর এবং তার একমাত্র অনুচর।\nএটি একটি 「অনুসন্ধান」-এর গল্প।"
  },
  Activity_45664_ActivityTips = {
    Text = "<Title:অংশগ্রহণের শর্ত>\n·চেতনা অভিযান 「নাইটের ইচ্ছা」 সাধারণ মোড সম্পন্ন করার পর অংশগ্রহণ করা যাবে। \n<Title:তদন্ত ইভেন্ট>\n·ইভেন্ট চলাকালীন, গোপনরক্ষক কোনো সম্পদ খরচ না করেই তদন্ত আনলক ও পরিচালনা করতে পারবেন, তদন্ত ইভেন্ট সম্পন্ন করার পর নির্মল কোর, তদন্ত ব্যাজ এবং গোপনরক্ষক অভিজ্ঞতা ইত্যাদি তদন্ত পুরস্কার পাওয়া যাবে।\n·ইভেন্ট শেষ হওয়ার পর, 「দৈত্যের পতন」-এর আনলক অবস্থা ও তদন্ত অগ্রগতি সংরক্ষিত থাকবে, ইভেন্ট চলাকালীন অসম্পূর্ণ তদন্ত ইভেন্ট সম্পন্ন করার পরও ইভেন্ট চলাকালীন সময়ের মতো একই তদন্ত পুরস্কার পাওয়া যাবে; যদি ইভেন্ট চলাকালীন আনলক না করা হয়ে থাকে, তাহলে ইভেন্ট শেষ হওয়ার পর বাস্তবতার উৎস×3 খরচ করে আনলক করা যাবে।<Title:সীমিত সময়ের পুরস্কার>\n·ইভেন্ট চলাকালীন সীমিত সময়ের পুরস্কার উন্মুক্ত হবে, গোপনরক্ষক 「দৈত্যের পতন」 সাধারণ মোড ক্লিয়ার এবং 「দৈত্যের পতন」-এর তদন্ত ইভেন্ট সম্পন্ন করার পর, ডাইমেনশন ক্রিস্টাল এবং সিলভার কোর পুরস্কার পেতে পারবেন! সীমিত সময়ের পুরস্কার শুধুমাত্র ইভেন্ট চলাকালীন উন্মুক্ত থাকবে, ইভেন্ট শেষ হওয়ার পর সম্পন্ন ও সংগ্রহ করা যাবে না।"
  },
  Activity_45664_UnlockConditionExplanation = {
    Text = "চেতনা অবগাহন 「নাইটের ইচ্ছা」 সম্পন্ন করার পর আনলক"
  },
  Activity_46167_ActivityName = {
    Text = "বিভক্ত রোগী·বিশৃঙ্খলা"
