  Activity_46167_ActivityTips = {
    Text = "<Title:ইভেন্টের নিয়ম>\n·「বিভক্ত রোগী·বিশৃঙ্খলা」ইভেন্ট চলাকালীন, কিপার「24」অন্তর্ভুক্ত সিস্টেম প্রিসেট দল ব্যবহার করে নির্ধারিত স্টেজ সীমাহীনবার অভিজ্ঞতা করতে পারবেন।\n·ইভেন্ট স্টেজ অভিজ্ঞতার সময়, দলের অ্যাওয়েকেনার পরিবর্তন করা যাবে না।\n<Title:ইভেন্ট পুরস্কার>\n·প্রথমবার স্টেজ চ্যালেঞ্জ সম্পন্ন করার পর, ইভেন্ট ইন্টারফেসে ট্রায়াল পুরস্কার সংগ্রহ করা যাবে।"
  },
  Activity_46168_ActivityName = {
    Text = "মাথা-শিকারী জাদুকরী"
  },
  Activity_46168_ActivityTips = {
    Text = "<Title:ইভেন্টের নিয়ম>\n·「মাথা-শিকারী জাদুকরী」ইভেন্ট চলাকালীন, গোপনরক্ষক দাফদেল অন্তর্ভুক্ত সিস্টেম প্রিসেট দল ব্যবহার করে নির্দিষ্ট স্টেজ সীমাহীনবার অভিজ্ঞতা করতে পারবেন।\n·ইভেন্ট স্টেজ অভিজ্ঞতার সময়, দলের জাগ্রত সত্তা পরিবর্তন করা যাবে না।\n<Title:ইভেন্ট পুরস্কার>\n·প্রথমবার স্টেজ চ্যালেঞ্জ সম্পন্ন করার পর, ইভেন্ট ইন্টারফেসে ট্রায়াল পুরস্কার সংগ্রহ করা যাবে।"
  },
  Activity_46609_ActivityName = {
    Text = "বহুস্তরীয় নিরাময়"
  },
  Activity_46609_ActivityPlot = {
    Text = "হিস্টিরিয়া। কেউ বলে ম্যানিয়া, কেউ বলে মনের ভাঙন; এই যুগে এই রোগ নির্ণয় মানেই মৃত্যুদণ্ড। সৌভাগ্যবশত, মিথ্যাগের বিজ্ঞানী ও অনুসন্ধান কর্মকর্তারা নিজেদের এক বিশেষ উন্মাদনায় আক্রান্ত: তারা এই সন্ত্রাসকে জয় করতেই বদ্ধপরিকর।"
  },
  Activity_46609_ActivityStageEndContent = {
    Text = "ইভেন্টটি সমাপ্ত হয়েছে। বর্তমানে কেবল 「অহং বিশ্লেষণ」 সংগ্রহযোগ্য।"
  },
  Activity_46609_ActivityTips = {
    Text = "<Title:ইভেন্ট সারসংক্ষেপ>\n1. ইভেন্ট চলাকালে, গোপনরক্ষকেরা সীমিত সময়ের গেমপ্লে মোড 「মেমরি এনকোডিং」, 「এজ স্টোরেজ」 এবং 「অর্জন পুরস্কার」-এর মাধ্যমে ইভেন্ট মুদ্রা 「মেমরি পাজল」 সংগ্রহ করতে পারবেন। 「মেমরি পাজল」 ব্যবহার করে 「পার্সোনালিটি অ্যানালাইসিস」-এ বিভিন্ন সামগ্রী কেনা যাবে, যার মধ্যে রয়েছে ইভেন্ট-এক্সক্লুসিভ SR নিয়তিচক্র 「রৌপ্য কডের সংকল্প」, লুমিনাস কোর, পিওর কোর, ইথেরিক স্টোন এবং প্রাচুর্যপূর্ণ উন্নয়ন উপকরণ।\n2. 「টাস্ক রেকর্ড: ট্র্যাঙ্কুইল ফিশন」 সম্পন্ন করলে নতুন পসি 「তার সমস্তটুকু」 প্রাপ্ত হবে। ইভেন্ট চলাকালে 「টাস্ক রেকর্ড: ট্র্যাঙ্কুইল ফিশন」 সীমিত বিনামূল্যে আনলক থাকবে, এবং ইভেন্ট অর্জন সম্পন্ন করলে ইভেন্ট-এক্সক্লুসিভ অবতার 「রৌপ্য চাবির নামে: 「24」!」-ও পাওয়া যাবে।\n\n<Title:ইভেন্ট সময়সূচি>\n1. 27 এপ্রিল, 9:00 – 18 মে, 9:00 (GMT+8): সব ইভেন্ট গেমপ্লে মোড খোলা থাকবে, এবং 「টাস্ক রেকর্ড: ট্র্যাঙ্কুইল ফিশন」 সীমিত বিনামূল্যে আনলক থাকবে।\n2. 18 মে, 9:00 – 25 মে, 9:00 (GMT+8): কেবল 「পার্সোনালিটি অ্যানালাইসিস」 এবং অর্জন পুরস্কার খোলা থাকবে। 「টাস্ক রেকর্ড: ট্র্যাঙ্কুইল ফিশন」 আনলক করতে 7টি রিয়ালিটি ভার্জ খরচ করতে হবে।\n\n<Title:মেমরি এনকোডিং>\n1. 「মেমরি এনকোডিং」-এ মোট 5টি স্তর রয়েছে। 「টাস্ক রেকর্ড: ট্র্যাঙ্কুইল ফিশন」-এর 2/4/6/8/10 নম্বর স্তর সম্পন্ন করে এগুলো ধারাবাহিকভাবে আনলক করা যাবে।\n2. প্রতিটি স্তরে 7টি করে কঠিনতা রয়েছে, সুপারিশকৃত লেভেল 15 থেকে 65 পর্যন্ত। সব কঠিনতা ডিফল্টভাবে আনলক থাকে। প্রতিটি স্তরের শত্রু ও ইভেন্ট এলোমেলোভাবে পরিবর্তিত হতে পারে।\n3. অ্যালামনাই সহায়তা এবং 「রেজোন্যান্স: ডিসোসিয়েটিভ সিনড্রোম」 ব্যবহার করে স্তরগুলো আরও সহজে অতিক্রম করা যাবে।\n4. প্রতিটি চ্যালেঞ্জে 120 মেনোফিন খরচ হয়। কঠিনতা যত বেশি, স্তর সম্পন্নের পর তত বেশি 「মেমরি পাজল」 পাওয়া যাবে। অতিরিক্তভাবে, গোপনরক্ষকেরা ডাবল চ্যালেঞ্জ বেছে নিতে পারেন; এতে 240 মেনোফিন খরচ হবে এবং প্রাপ্ত 「মেমরি পাজল」 ও গোপনরক্ষকের অভিজ্ঞতা দ্বিগুণ হবে।\n\n<Title:র‍্যাশনাল বোনাস>\n1. নির্দিষ্ট অ্যাওয়েকনার বা নিয়তিচক্র (মোতায়েন করা আবশ্যক নয়) থাকা গোপনরক্ষকেরা 「মেমরি এনকোডিং」 স্তর পুরস্কারে 「মেমরি পাজল」-এর অতিরিক্ত ড্রপ বোনাস পাবেন, বিস্তারিত নিম্নরূপ:\nঅ্যাওয়েকনার 「24」: এনলাইটেনমেন্ট 0/1/2/3 ও তদূর্ধ্ব, বোনাস 15%/20%/25%/30%।\nঅ্যাওয়েকনার 「ড্যাফোডিল」: এনলাইটেনমেন্ট 0/1/2/3 ও তদূর্ধ্ব, বোনাস 15%/20%/25%/30%।\nSSR নিয়তিচক্র 「বিকৃত দেহের প্রতিগ্রাস」: স্ট্যাক লেভেল 0/1/2/3 ও তদূর্ধ্ব, বোনাস 15%/20%/25%/30%।\nSSR নিয়তিচক্র 「অমূল্য সংগ্রহ」: স্ট্যাক লেভেল 0/1/2/3 ও তদূর্ধ্ব, বোনাস 15%/20%/25%/30%।\nSR নিয়তিচক্র 「রৌপ্য কডের সংকল্প」: স্ট্যাক লেভেল 0/1/2/3 ও তদূর্ধ্ব, বোনাস 15%/20%/25%/30%।\n2. ভিন্ন অ্যাওয়েকনার বা নিয়তিচক্রের 「র‍্যাশনাল বোনাস」 যোগ করে গণনা করা হয়।\n\n<Title:রেজোন্যান্স: ডিসোসিয়েটিভ সিনড্রোম>\n1. ইভেন্ট অর্জন সম্পন্ন করে গোপনরক্ষকেরা 「ডিভাইডেড হার্ট」 পেতে পারেন।\n2. 「ডিভাইডেড হার্ট」 ব্যয় করে 「রেজোন্যান্স: ডিসোসিয়েটিভ সিনড্রোম」 সক্রিয় করলে নিম্নলিখিত বোনাস পাওয়া যাবে:\n(1) ইভেন্ট গেমপ্লে মোড 「মেমরি এনকোডিং」 এবং 「টাস্ক রেকর্ড: ট্র্যাঙ্কুইল ফিশন」-এ গোপনরক্ষকদের শক্তি বৃদ্ধি পাবে, ফলে চ্যালেঞ্জ সহজ হবে।\n(2) 「মেমরি এনকোডিং」 চ্যালেঞ্জ সম্পন্নের পর প্রাপ্ত পুরস্কার বৃদ্ধি পাবে।\n(3) ইভেন্ট গেমপ্লে মোড 「এজ স্টোরেজ」 সক্রিয় হবে।\n\n<Title:এজ স্টোরেজ>\nরেজোন্যান্স 「রোগনির্ণয়: বিভক্ত সত্তা」 সক্রিয় করার পর, প্রতি ঘন্টায় স্বয়ংক্রিয়ভাবে 60টি 「স্মৃতি পাজল α」 প্রাপ্ত হবে, সর্বোচ্চ 25 ঘন্টা পর্যন্ত সঞ্চিত থাকতে পারবে।\n\n<Title:টাস্ক রেকর্ড>\n1. ইভেন্ট চলাকালে 「টাস্ক রেকর্ড: ট্র্যাঙ্কুইল ফিশন」 বিনামূল্যে আনলক করা যাবে। 「ট্র্যাঙ্কুইল ফিশন」-এর নতুন তদন্ত ইভেন্ট প্রতি 2 দিনে একবার করে প্রকাশিত হবে। তদন্ত ইভেন্ট সম্পন্ন করলে পসি 「তার সমস্তটুকু」, পিওর কোর, অনুসন্ধান ব্যাজ এবং গোপনরক্ষকের অভিজ্ঞতা ইত্যাদি পুরস্কার পাওয়া যাবে।\n2. ইভেন্ট শেষ হওয়ার পরও 「টাস্ক রেকর্ড: ট্র্যাঙ্কুইল ফিশন」-এর তদন্ত অগ্রগতি সংরক্ষিত থাকবে। ইভেন্ট চলাকালে শুরু হলেও অসমাপ্ত থাকা তদন্ত ইভেন্টগুলো পরবর্তীতেও সম্পন্ন করে একই তদন্ত পুরস্কার পাওয়া যাবে। যদি ইভেন্ট চলাকালে 「টাস্ক রেকর্ড: ট্র্যাঙ্কুইল ফিশন」 আনলক না করা হয়ে থাকে, ইভেন্ট শেষে 7টি রিয়ালিটি ভার্জ ব্যয় করে তা এখনও আনলক করা যাবে।\n3. ইভেন্ট চলাকালে সীমিত সময়ের অর্জন পুরস্কার চালু থাকবে। 「টাস্ক রেকর্ড: ট্র্যাঙ্কুইল ফিশন」-এর সব তদন্ত ইভেন্ট সম্পন্ন করলে ইভেন্ট অর্জনে অবতার 「রৌপ্য চাবির নামে: 「24」」 দাবি করা যাবে। অর্জন পুরস্কার কেবল ইভেন্ট চলাকালেই উপলব্ধ; ইভেন্ট শেষ হওয়ার পর এগুলো আর সম্পন্ন বা দাবি করা যাবে না।\n\n\n"
