  Activity_48827_ActivityPlot = {
    Text = "অসম্পূর্ণ পরিসংখ্যান অনুযায়ী, গত ছয় মাসে স্কুল বিড়ালের টুপিতে শিক্ষার্থীরা হাজার হাজার বার চাপড় মেরেছে, অনেক ক্ষুদ্র ও অলক্ষিত সিলভার কোর মাটিতে পড়ে গেছে কিন্তু কেউ তুলে নেয়নি। পরিচ্ছন্নতা কর্মীরা এতে বেশ বিরক্ত। এখন স্কুল কর্তৃপক্ষ এই সিলভার কোরগুলো সংগ্রহ করে পরিষ্কার করে হারানো জিনিসপত্র বিভাগে রেখে দিয়েছে, মালিকদের অনুরোধ করা হচ্ছে সময়মতো নিজে এসে সংগ্রহ করতে।"
