  Activity_53727_ActivityTips = {
    Text = "<Title:ইভেন্ট পরিচিতি>\n·「প্রত্যাবর্তন দিবস」 মিশন 4টি গ্রুপে বিভক্ত, যথাক্রমে ইভেন্ট শুরুর 1ম, 2য়, 3য় ও 4র্থ দিনে আনলক হবে।\n·সিক্রেটকিপাররা 「প্রত্যাবর্তন দিবস」 মিশন সম্পন্ন করে 「প্রত্যাবর্তন আমন্ত্রণ」 অর্জন করতে পারবে।\n·「প্রত্যাবর্তন আমন্ত্রণ」 ব্যবহার করে 「প্রত্যাবর্তন শপ」 থেকে সমৃদ্ধ পুরস্কার বিনিময় করা যাবে।"
