  Activity_53729_ActivityTips = {
    Text = "<Title:ইভেন্ট পরিচিতি>\n·সিক্রেটকিপাররা প্রতিদিন লগইন করার পর 「স্কুলে প্রত্যাবর্তন」 থেকে দৈনিক সাইন-ইন পুরস্কার সংগ্রহ করতে পারবে।\n·পুরস্কার সিক্রেটকিপারের ক্রমবর্ধমান লগইন অনুযায়ী ক্রমান্বয়ে আনলক হবে, দৈনিক সাইন-ইন পুরস্কার সকাল 9টায়(GMT+8) রিফ্রেশ হবে।"
