  Activity_53829_ActivityStageEndContent = {
    Text = "ইভেন্ট শেষ হয়েছে, বর্তমানে শুধুমাত্র 「সোনালি-লাল উৎসব」 এ অংশগ্রহণ করা যাবে"
  },
  Activity_53829_ActivityTips = {
    Text = "<Title:ইভেন্ট সারসংক্ষেপ>\n1. ইভেন্ট চলাকালীন, কিপাররা সীমিত-সময়ের গেমপ্লে 「রোজ মেমরিজ」 এবং 「অর্জন পুরস্কার」 থেকে ইভেন্ট মুদ্রা 「স্পিরিট বার্ড ফ্যান」 সংগ্রহ করতে পারবেন। 「স্পিরিট বার্ড ফ্যান」 ব্যবহার করে 「গোল্ডেন সেলিব্রেশন」-এ উদার পুরস্কার বিনিময় করা যাবে, যার মধ্যে রয়েছে ইভেন্ট-এক্সক্লুসিভ SR নিয়তিচক্র 「লক্ষ স্নেহময় দৃষ্টি」, পিওর কোর, লুমিনাস কোর, ইথেরিক শার্ড, মিমেটিক ক্রিস্টাল ইত্যাদি।\n2. ইভেন্ট চলাকালীন, 「অর্জন পুরস্কার」 টাস্ক সম্পন্ন করলে ইভেন্ট-এক্সক্লুসিভ অ্যাভাটার 「রৌপ্য চাবির নামে: সোরেল」, ইভেন্ট-এক্সক্লুসিভ SR নিয়তিচক্র 「লক্ষ স্নেহময় দৃষ্টি」, সিলভার এবং প্রচুর ইভেন্ট মুদ্রা 「স্পিরিট বার্ড ফ্যান」 পাওয়া যাবে।\n3. ইভেন্ট চলাকালীন, 「স্পেশাল মিশন রিপোর্ট: রোজ ইউলজি」 সীমিত বিনামূল্যে আনলক থাকবে।\n\n<Title:ইভেন্টের সময়কাল>\n1. 1 জুলাই 9:00 থেকে 15 জুলাই 9:00 (GMT+8) পর্যন্ত সব ইভেন্ট কনটেন্ট সংগ্রহযোগ্য থাকবে।\n2. 15 জুলাই 9:00 থেকে 22 জুলাই 9:00 (GMT+8) পর্যন্ত শুধুমাত্র 「গোল্ডেন সেলিব্রেশন」 এবং 「অর্জন পুরস্কার」 সংগ্রহযোগ্য থাকবে; অন্যান্য কনটেন্ট আর অ্যাক্সেস করা যাবে না।\n\n<Title:রোজ মেমরিজ>\n1. 「রোজ মেমরিজ」-এ মোট 9টি স্তর থাকবে, প্রতিদিন একটি করে স্তর খুলবে।\n2. প্রতিটি চ্যালেঞ্জে 120 মেনোফিন খরচ হবে, এবং বিভিন্ন উপকরণের সঙ্গে ইভেন্ট মুদ্রা 「স্পিরিট বার্ড ফ্যান」 পাওয়া যাবে।\n3. এই ইভেন্টের স্তরগুলো সরাসরি কমব্যাট উপকরণ স্তর। এগুলো ক্লিয়ার করলে 「রিপ্লে」 করা যাবে! প্রতিটি 「রিপ্লে」-তে 120 মেনোফিন খরচ হবে।\n4. নোট: 「রিপ্লে」 ব্যবহার করলে অ্যাফিনিটি পাওয়া যাবে না।\n\n<Title:ফ্যান বুস্ট>\n1. নির্দিষ্ট অ্যাওয়েকেনার বা নিয়তিচক্র (দলে নামানো বাধ্যতামূলক নয়) থাকলে 「রোজ মেমরিজ」 স্তরগুলোতে (রিপ্লেসহ) 「স্পিরিট বার্ড ফ্যান」 ড্রপ বৃদ্ধি পাবে, নিম্নরূপ:\nঅ্যাওয়েকেনার 「সোরেল」: আত্মজাগরণ 0/1/2/3+, বুস্ট 20%/30%/40%/50%\nSSR নিয়তিচক্র 「গোলাপের নামে」: স্ট্যাক লেভেল 0/1/2/3+, বুস্ট 20%/30%/40%/50%\nSR নিয়তিচক্র 「লক্ষ স্নেহময় দৃষ্টি」: স্ট্যাক লেভেল 0/1/2/3+, বুস্ট 20%/30%/40%/50%\n2. ভিন্ন অ্যাওয়েকেনার বা নিয়তিচক্র থেকে প্রাপ্ত ফ্যান বুস্ট একে অপরের সঙ্গে যোগ হয়।\n\n<Title:স্পেশাল মিশন রিপোর্ট>\n1. ইভেন্ট চলাকালীন, যারা পূর্বে 「স্পেশাল মিশন রিপোর্ট: রোজ ইউলজি」 আনলক করেছেন, তারা পুনরায় আনলক করার সময় ক্ষতিপূরণ হিসেবে 600টি 「স্পিরিট বার্ড ফ্যান」 পাবেন।\n2. 「রোজ ইউলজি」-তে, কিপাররা প্রি-সেট স্টোরিলাইন 「সোরেল」 সমন্বিত একটি বিশেষ লাইনআপ ব্যবহার করে চ্যালেঞ্জে অংশ নেবেন।"
  },
  Activity_53829_BannerText = {
    Text = "সীমিত সময়ের ইভেন্ট এখন উপলব্ধ!"
  },
  Activity_54375_ActivityName = {
    Text = "গোলাপের প্রশস্তি"
  },
  Activity_54375_ActivityPlot = {
    Text = "ভদ্রমহিলা ও ভদ্রলোকগণ।\nস্নিগ্ধ রাত্রি তার পর্দা সরিয়ে নিয়েছে—প্রস্তুত করুন আপনার শ্রেষ্ঠ পানীয়।\nএ এক দীর্ঘ কাহিনি। অবকাশ নিয়ে আপনাদের তা শোনাতে দিন।"
  },
  Activity_54375_ActivityTips = {
    Text = "<Title:অংশগ্রহণের শর্তাবলি>\nঅংশগ্রহণ করতে 「তদন্ত অভিযান」 2-9(সাধারণ) সম্পন্ন করুন।\n<Title:তদন্ত ইভেন্ট>\nইভেন্ট চলাকালীন, প্রতিদিন 「গোলাপের প্রশস্তি」 থেকে একটি নতুন তদন্ত ইভেন্ট চালু হবে। রক্ষকেরা সামগ্রী ব্যয় না করেই এগুলো আনলক ও তদন্ত করতে পারবেন। তদন্ত ইভেন্ট সম্পন্ন করার পর নির্মল মর্ম, অনুসন্ধান ব্যাজ, এবং রক্ষক অভিজ্ঞতা ইত্যাদি পুরস্কার প্রাপ্ত হবে।\nইভেন্ট শেষ হওয়ার পরও 「গোলাপের প্রশস্তি」-এর তদন্ত অগ্রগতি ধরে রাখা হবে, এবং রক্ষকেরা বিশেষ অপসে ডি-জুয়েল ব্যয় করে অসম্পন্ন তদন্তগুলো আনলক করতে পারবেন। ইভেন্ট চলাকালীন অসম্পন্ন তদন্ত ইভেন্ট সম্পন্ন করলে, ইভেন্ট চলাকালীন প্রাপ্ত পুরস্কারের সঙ্গেই সামঞ্জস্যপূর্ণ পুরস্কার প্রদান করা হবে।<Title:সীমিত সময়ের পুরস্কার>\nইভেন্ট চলাকালীন সীমিত সময়ের পুরস্কার সংগ্রহযোগ্য থাকবে। রক্ষকেরা 「গোলাপের প্রশস্তি」(সাধারণ) মোড সম্পূর্ণ করে এবং 「গোলাপের প্রশস্তি」-এর তদন্ত ইভেন্টসমূহ শেষ করে নির্মল মর্ম, পরশমণি, এবং রৌপ্য অর্জন করতে পারবেন! সীমিত সময়ের পুরস্কার কেবল ইভেন্ট চলাকালীনই সংগ্রহযোগ্য, ইভেন্ট শেষ হওয়ার পর এগুলো আর সম্পন্ন বা দাবি করা যাবে না।"
  },
  Activity_54402_ActivityName = {
    Text = "বিভক্ত রোগী·বিশৃঙ্খলা"
