  Activity_54403_ActivityTips = {
    Text = "<Title:ইভেন্টের নিয়ম>\n·「দ্বারের চাবি」ইভেন্ট চলাকালীন, সিক্রেটকিপার তাভিসহ সিস্টেম প্রিসেট দল ব্যবহার করে নির্দিষ্ট স্টেজ সীমাহীনবার অভিজ্ঞতা করতে পারবেন।\n·ইভেন্ট স্টেজ অভিজ্ঞতার সময়, দলের অ্যাওয়েকেনড সদস্য পরিবর্তন করা যাবে না।\n<Title:ইভেন্ট পুরস্কার>\n·প্রথমবার স্টেজ চ্যালেঞ্জ সম্পন্ন করার পর, ইভেন্ট ইন্টারফেসে ট্রায়াল পুরস্কার সংগ্রহ করা যাবে।"
