  Activity_56429_ActivityPlot = {
    Text = "সে সবসময় দুনিয়ার এক ধাপ আগে হাঁটে。\nএক পা, দুই পা—তার পদচিহ্নই সবার জন্য সলতের পথ জ্বেলে দেয়。\nতবু বোকারা খুব তাড়াতাড়ি ভুলে যায়:\nপ্রতিভা আর উন্মাদনার ফাঁক\nমোটে আধা পা।"
