  Activity_56430_ActivityName = {
    Text = "অদৃশ্য সিম্ফনি"
  },
  Activity_56430_ActivityPlot = {
    Text = "সিম্ফনি হলো বুননের শিল্প, বিভিন্ন বাদ্যযন্ত্রের গতিপথ মিলেমিশে এক জটিল নকশা তৈরি করে।\nতার বোনা জালে, প্রতিটি স্বরলিপি নিজ নিজ দায়িত্ব পালন করবে।\nশোনো, এক অতুলনীয় সিম্ফনি এখনই শুরু হতে চলেছে।"
