  Activity_56431_ActivityName = {
    Text = "নক্ষত্র সুস্থিত"
  },
  Activity_56431_ActivityPlot = {
    Text = "নক্ষত্রমণ্ডলী সুস্থিত হওয়ার মুহূর্ত ঘনিয়ে আসছে, বুকের মধ্যে ভ্রূণের নড়াচড়া ঢোলের মতো বাজছে।\nবহু বছর ধরে তাকে যন্ত্রণা দেওয়া অন্ধকার রাতের দুঃস্বপ্ন, অগণিত ভক্তদের অশ্রুসিক্ত পরিসমাপ্তির সাথে এসে পৌঁছেছে।\nতাঁর@1অন্ধকার@2থেকে, মহান@3পৃথিবীতে অবতীর্ণ হলেন।"
