  Activity_56432_ActivityPlot = {
    Text = "এলওয়ার্থের বরফ কখনো গলে না, ঠিক যেমন তার ঘৃণা।\nযখন ভবিষ্যৎ ও অতীতের হাত পরস্পরে মিলিত হয়, যোদ্ধা তার তলোয়ার উঁচিয়ে ধরে, নিয়তির বিরুদ্ধে প্রতিশোধের আক্রমণ শুরু করে।\nযখন সে কালো ঢেউয়ের মুখোমুখি হয়, তুমি তার পতাকা।"
