  Activity_61156_ActivityName = {
    Text = "অন্তিম ভ্রমণকথা"
  },
  Activity_61156_ActivityTips = {
    Text = "ইভেন্টের নিয়মাবলী：\n1、সিক্রেটকিপার নির্ধারিত ভ্রমণকথা মিশন সম্পন্ন করার পর, 「অন্তিম ভ্রমণকথা」-তে পুরস্কার সংগ্রহ করতে পারবেন।\n2、「অন্তিম ভ্রমণকথা」স্থায়ীভাবে উন্মুক্ত।\n3、「প্রিমিয়াম ভ্রমণকথা」আনলক করার পর, মিশন সম্পন্ন করলে অতিরিক্ত পুরস্কার সংগ্রহ করা যাবে।\n4、অনুগ্রহ করে মনে রাখবেন: এই ইভেন্টে আনলক করা 「প্রিমিয়াম ভ্রমণকথা」শুধুমাত্র এই ইভেন্টে কার্যকর। সিক্রেটকিপার অনুগ্রহ করে বিবেচনা করে যুক্তিসঙ্গতভাবে খরচ করুন।"
  },
  Activity_61369_ActivityName = {
    Text = "ক্রমবর্ধমান সুরলহরী"
  },
  Activity_61369_ActivityPlot = {
    Text = "গোপনরক্ষক নিম্নলিখিত সীমিত ভাগ্যচক্রের মধ্যে যেকোনো একটি বেছে জাগ্রত করতে পারবেন!"
  },
  Activity_61369_ActivityTips = {
    Text = "<Title:পরিচিতি>\nকৃষ্ণ পুকুরে ঢেউ উত্তাল, ভাগ্যচক্র ঘুরে ফিরে আসে। হ্যামলিনের সুরের টানে, অসীম সুরলহরী একত্রে বেজে ওঠে, তোমার পথচলার যাত্রার ভাগ্যচক্র রচনা করে। তাদের সহায়তা তোমার সাথে থাকুক চূড়ান্ত সোনাটার বিরতিচিহ্ন পর্যন্ত।\n\n<Title:ইভেন্টের নিয়ম>\n·ইভেন্ট চলাকালীন মাত্র একদিন লগইন করলেই নিম্নলিখিত 12টি সীমিত ভাগ্যচক্রের মধ্যে যেকোনো একটি বেছে জাগ্রত করা যাবে, যার মধ্যে রয়েছে: 「দেবরাজের স্তোত্র」, 「সবচেয়ে মূল্যবান সংগ্রহ」, 「গোলাপের নামে」, 「যন্ত্রণা অতিক্রম」, 「গোপন জন্ম」, 「রানির বিধান」, 「দৈববাণী প্রস্তরফলক」, 「বিকৃত দেহের প্রতিগ্রাস」, 「ভক্তির মহাশক্তি」, 「কবিতার শেষ পঙ্ক্তি」, 「করুণাময় প্রতিপালন」, 「সৌভাগ্যের সময়」।"
  },
  Activity_61369_BannerText = {
    Text = "সীমিত ভাগ্যচক্র বিনামূল্যে সংগ্রহ করুন"
