  Activity_61370_ActivityName = {
    Text = "বিশুদ্ধ রৌপ্যের প্রারম্ভিক হৃদয়"
  },
  Activity_61370_ActivityPlot = {
    Text = "প্রতিদিন লগইন করে স্মারক সীমিত SSR ভাগ্যচক্র 「বিশুদ্ধ রৌপ্য হৃদয়」 সংগ্রহ করুন, মোট 16টি সংগ্রহ করা যাবে!"
  },
  Activity_61370_ActivityTips = {
    Text = "<Title:পরিচিতি>\nবিশ্ব যতই উল্টে যাক, যতক্ষণ প্রত্যেকে সেই আদি, স্বচ্ছ বিশুদ্ধ রৌপ্য হৃদয় রক্ষা করবে, গল্প শেষ পর্যন্ত আবার ফিরে আসবে, নতুন জীবন জন্ম নেবে ধ্বংসপ্রাপ্ত ভূমিতে।\n\n<Title:ইভেন্টের নিয়ম>\n·ইভেন্ট চলাকালীন, গোপনরক্ষক প্রতিদিন লগইন করার পর 「বিশুদ্ধ রৌপ্যের আদি হৃদয়」 থেকে স্মারক সীমিত SSR ভাগ্যচক্র 「বিশুদ্ধ রৌপ্যের আদি হৃদয়」 সংগ্রহ করতে পারবেন, মোট 16 বার সংগ্রহ করা যাবে।\n·পুরস্কার গোপনরক্ষকের মোট লগইনের ভিত্তিতে ক্রমানুসারে আনলক হবে, দৈনিক লগইন পুরস্কার সকাল 9টায়(GMT+8) রিফ্রেশ হবে।"
  },
