  Activity_65387_ActivityName = {
    Text = "স্কুল বিড়ালের ক্ষমা"
  },
  Activity_65387_ActivityPlot = {
    Text = "সম্প্রতি স্কুল কর্তৃপক্ষের সুরক্ষা ব্যবস্থার ত্রুটির কারণে, <Del:\"অস্থায়ী টেক্সট, লাল বিন্দু\"> ক্ষয়ের আক্রমণে ক্যাম্পাসে সমস্যা ক্রমশ বাড়ছে, যা শিক্ষার্থীদের অনেক অসুবিধার সৃষ্টি করেছে। তাই স্কুল প্রশাসন বিশেষভাবে একাধিক সরবরাহ কেন্দ্র স্থাপন করেছে, ক্ষতিপূরণ হিসেবে শিক্ষার্থীদের মধ্যে সামগ্রী বিতরণ করতে। (সুবিধা ব্যবস্থাপনার ত্রুটির দায়িত্ব বিবেচনায়, এবারের সরবরাহ সামগ্রী সম্পূর্ণরূপে স্কুল বিড়ালের দ্বারা বহন করা হচ্ছে।)"
  },
  Activity_65387_ActivityTips = {
    Text = "<Title:পরিচিতি>\nসম্প্রতি স্কুল কর্তৃপক্ষের সুরক্ষা ব্যবস্থার ত্রুটির কারণে, <Del:\"অস্থায়ী টেক্সট, লাল বিন্দু\"> ক্ষয়ের আক্রমণে ক্যাম্পাসে সমস্যা ক্রমশ বাড়ছে, যা শিক্ষার্থীদের অনেক অসুবিধার সৃষ্টি করেছে। তাই স্কুল প্রশাসন বিশেষভাবে একাধিক সরবরাহ কেন্দ্র স্থাপন করেছে, ক্ষতিপূরণ হিসেবে শিক্ষার্থীদের মধ্যে সামগ্রী বিতরণ করতে। (সুবিধা ব্যবস্থাপনার ত্রুটির দায়িত্ব বিবেচনায়, এবারের সরবরাহ সামগ্রী সম্পূর্ণরূপে স্কুল বিড়ালের দ্বারা বহন করা হচ্ছে।)\n\n<Title:ইভেন্টের নিয়ম>\n·ইভেন্ট চলাকালীন, গোপনরক্ষক প্রতিদিন লগইন করার পর 「স্কুল বিড়ালের ক্ষমা「 থেকে 「সিলভার কোর「 × 500 সংগ্রহ করতে পারবেন, সর্বোচ্চ 5 বার সংগ্রহ করা যাবে।\n·পুরস্কার গোপনরক্ষকের মোট লগইনের ভিত্তিতে ক্রমানুসারে আনলক হবে, দৈনিক লগইন পুরস্কার সকাল 9টায় (GMT+8) রিফ্রেশ হবে।"
  },
