  Activity_66375_ActivityPlot = {
    Text = "তাঁর দৃষ্টি অসংখ্য মাত্রা জুড়ে বিচরণ করে, আর তাঁর চোখে চোখ রাখে অগণিত রূপালি ছায়ামূর্তি। \nতারা ক্ষুদ্র, ভঙ্গুর। তারা স্মৃতি রক্ষার জন্য লড়াই করে, মৃত্যু পর্যন্ত অবিচল।"
