  Activity_66375_ActivityStageEndContent = {
    Text = "কার্যকলাপ সম্পন্ন হয়েছে, আপনি তদন্ত চালিয়ে যেতে পারেন।"
  },
  Activity_66375_ActivityTips = {
    Text = "<Title:সহযোগী যুদ্ধ: আদিম>\n「সহযোগী যুদ্ধ: আদিম「 মোট 7টি একবারই-খেলতে-পারার স্তর নিয়ে গঠিত, যা সরাসরি আদিমের ভিশনকে চ্যালেঞ্জ করে। ইভেন্টের প্রথম দিনে প্রথম 3টি স্তর খুলবে, এরপর প্রতি 3 দিনে 1টি করে স্তর উন্মুক্ত হবে।\nপ্রতিবার আপনি সংশ্লিষ্ট আদিমের ভিশনকে সফলভাবে চ্যালেঞ্জ করলে, আপনি সেই ভিশনের উপযোগী পুরস্কার পাবেন।\nপ্রতিটি ধরনের আদিমের ভিশনের একাধিক ক্লোন থাকে। যখনই কোনো কিপার কোনো নির্দিষ্ট ধরনের আদিমের ভিশনকে সফলভাবে চ্যালেঞ্জ করে, সেই ধরনের 「বিশ্ব অবশেষ গণনা「 1 কমে যায়। যখন ঐ ধরনের সব ক্লোন পরাস্ত হয়, তখন সংশ্লিষ্ট স্তরটি বন্ধ হয়ে যাবে এবং আর কখনো চ্যালেঞ্জ করা যাবে না।\nসব স্তরই 「আঞ্চলিক ডি-ইফেক্টের ডি-জোয়ার: সমাপ্তি「র প্রভাবে থাকে, তবে প্রতিটি স্তর ভিন্ন ভিন্ন 「নির্মল মর্ম「 রেলিক প্রদান করবে, যা আপনাকে শক্তিশালী বোনাস দেবে। অতিরিক্তভাবে, প্রতিটি স্তর একটি 「জ্ঞানচক্ষু「 রেলিকও দেবে, যা যুদ্ধের শুরুতেই তাওইলকে 120 আলিয়েমাস প্রদান করবে, এবং তাওইল কর্তৃক সৃষ্ট সব ক্ষতি, ঢাল ও নিরাময় প্রভাব 50% বৃদ্ধি করবে।\nসব স্তরেই সহায়তা নির্বাচন করা বাধ্যতামূলক। পুরো ইভেন্ট জুড়ে, প্রতিটি পারস্পরিক অনুসরণকারী কিপার আপনাকে মাত্র একবারই সহায়তা দিতে পারবে। সহায়তা ব্যবহারের কারণে, ভিত্তিমূল পুরস্কারের ওপর অতিরিক্ত 50% সমসংস্থান হার পুরস্কার যোগ হবে।\nএই ইভেন্টে অংশ নিতে কিপারদের অন্তত 「তদন্ত অভিযান「 2-9 সম্পন্ন করতে হবে।\n\n<Title:তদন্ত অভিযান: শেষ অধ্যায়>\nপ্রতিটি আদিমের ভিশনের মূল দেহ এখনো আপনাকেই 「তদন্ত অভিযান「 9-5 থেকে 9-11-এ গিয়ে পরাস্ত করতে হবে। এই বিশেষ স্তরগুলোর কোনো অর্জন নেই, কোনো তারকা রেটিং নেই, 「জ্ঞানচক্ষু「 রেলিক বা সহায়তা ব্যবহার করা যায় না, এবং এগুলোর কঠিনতাও বেশি।\n「সহযোগী যুদ্ধ: আদিম「 ইভেন্ট শেষ হওয়ার পর, 「তদন্ত অভিযান: শেষ অধ্যায়「র পরবর্তী স্তরগুলো উন্মুক্ত হবে। যখন আপনি অন্যান্য কিপারদের সঙ্গে মিলে বিভিন্ন আদিমের ভিশনের সব ক্লোনকে সমূলে ধ্বংস করবেন, তখন আপনি আগাম 「তদন্ত অভিযান「 9-5 থেকে 9-11-এর সংশ্লিষ্ট স্তরগুলো আনলক করতে পারবেন।"
