  Activity_67718_ActivityName = {
    Text = "বসন্ত ঝরে যাওয়ার আগে·পুনরাবৃত্তি"
  },
  Activity_67718_ActivityPlot = {
    Text = "আগুন জ্বলার আগে বাগানে বালিকাদের হাসি প্রতিধ্বনিত হয়।\nএই সুন্দর অতীতে একটু থেমে থাকো, আমার বন্ধু।\nঅম্লান বসন্তের কাহিনিগুলো শোনো, নরম স্বরে বর্ণিত।"
