  Activity_67741_ActivityPlot = {
    Text = "ডলের অর্পিত কাজগুলো কখনোই সহজ নয়।\nযদিও সে বারবার সকলে-কে মনে করিয়ে দেয় “মজা করো”, প্রথমবার একদল অ্যাওয়েকেনারকে নিয়ে বেরোতে গিয়ে রক্ষকই বা কীভাবে অস্থির না হয়?\nতবু মনে রেখো, “মজা করো”, ঠিক আছে।"
