  Activity_67746_ActivityPlot = {
    Text = "কেউ জানে না কতকাল ধরে সে চরমের দ্বারের সামনে নীরব প্রহরী হয়ে দাঁড়িয়ে আছে।\nকোনো দৃশ্যমান জগতে প্রকাশ পাওয়ার ইচ্ছা তার ছিল না, না ছিল কোনো কাল-স্থানীয় স্রোতে ভেসে যাওয়ার বাসনা।\nসেখানে, সেই দ্বারের কাছে, সে ছিল অশান্তিহীন—\nযতক্ষণ না তার চোখ তোমার চোখের সঙ্গে মিলিত হলো।"
