  Activity_68349_ActivityTips = {
    Text = "<Title: তারকা অতিক্রম·সময়সীমিত প্রি-অর্ডার>\n·এই সময়সীমিত প্রি-অর্ডার ইভেন্টে 8টি গিফট প্যাক রয়েছে, যার মধ্যে প্রথম গিফট প্যাকটি সরাসরি বিনামূল্যে সংগ্রহ করা যাবে, 2-8 নম্বর গিফট প্যাক সংগ্রহ করতে「তারকা অতিক্রম·সময়সীমিত প্রি-অর্ডার」ক্রয় করতে হবে।\n·「তারকা অতিক্রম·সময়সীমিত প্রি-অর্ডার」ক্রয়ের পর অবিলম্বে 2 নম্বর গিফট প্যাকের পুরস্কার সংগ্রহ করা যাবে; পরবর্তী গিফট প্যাকগুলো সংগ্রহ করতে নির্দিষ্ট সময় অপেক্ষা করতে হবে।\n·「তারকা অতিক্রম·সময়সীমিত প্রি-অর্ডার」ক্রয়ের সময়সীমা রয়েছে, মেয়াদ উত্তীর্ণ হলে আর ক্রয় করা যাবে না। অনুগ্রহ করে গোপনরক্ষক বিবেচনা করে ক্রয় করুন।"
