  Activity_68410_ActivityName = {
    Text = "বৃষ্টিময় শহরের ছায়ামূর্তি"
  },
  Activity_68410_ActivityPlot = {
    Text = "ভেজা, কুয়াশাচ্ছন্ন বৃষ্টির আড়ালে অপেক্ষা করছে এক নিয়তিনির্ধারিত সাক্ষাৎ। তুমি তার নাম জানো, মুখ চিনো, আর তার কণ্ঠ এখনও তোমায় নিঃশব্দ নিশ্চিন্ততায় দোলায়। \nকিন্তু মনে রেখো—মানুষের কামনা পূরণে এত মরিয়া হয় কেবল দেবতা আর শয়তানই। \nএকটু আন্দাজ করো তো। সে আসলে কোনটি?"
  },
  Activity_68410_ActivityStageEndContent = {
    Text = "ইভেন্টটি সমাপ্ত হয়েছে। এখন তুমি কেবল \"জাদুকরীর ভাণ্ডার\"-এ অংশ নিতে পারবে।"
  },
  Activity_68410_ActivityTips = {
    Text = "<Title:ইভেন্ট সারসংক্ষেপ>\n1. ইভেন্ট চলাকালীন, কিপাররা সীমিত সময়ের গেমপ্লে 「উইচের দোকান「 এবং 「অর্জন পুরস্কার「 থেকে ইভেন্ট মুদ্রা সংগ্রহ করতে পারবেন। ইভেন্ট মুদ্রা 「উইচের ভাণ্ডার「-এ ব্যবহার করে আইটেম পুরস্কার বিনিময় করা যাবে, যার মধ্যে রয়েছে ইভেন্ট-সীমিত SR নিয়তিচক্র 「জাদুকরীর চওড়া কানার টুপি「, পরশমণি, পিওর কোর এবং লুমেন কোর।\n2. ইভেন্ট চলাকালীন, 「স্পেশাল ডিসপ্যাচ রেকর্ড: বৃষ্টিভেজা শহরের ছায়া「 বিনামূল্যে উন্মুক্ত থাকবে, এবং ইভেন্ট অর্জন সম্পন্ন করেও আপনি ইভেন্ট-সীমিত অবতার 「রৌপ্য চাবির নামে: ড্যাফোডিল「 পেতে পারবেন!\n\n<Title:ইভেন্টের সময়কাল>\n1. 24 ফেব্রুয়ারি 9:00 থেকে 10 মার্চ 9:00 পর্যন্ত (GMT+8), সব ইভেন্ট কনটেন্টে অংশগ্রহণ করা যাবে।\n2. 10 মার্চ 9:00 থেকে 17 মার্চ 9:00 পর্যন্ত (GMT+8), শুধুমাত্র 「উইচের ভাণ্ডার「 এবং 「অর্জন পুরস্কার「 উপলব্ধ থাকবে; অন্যান্য কনটেন্ট শেষ হয়ে যাবে এবং আর প্রবেশযোগ্য থাকবে না।\n\n<Title:উইচের দোকান>\n1. 「উইচের দোকান「-এ 5টি লেভেল রয়েছে, প্রতি 2 দিন পরপর 1টি করে লেভেল স্বয়ংক্রিয়ভাবে খুলে যাবে।\n2. প্রতিটি চ্যালেঞ্জে 120 মেনোফিন খরচ হবে, এবং সফল চ্যালেঞ্জে ইভেন্ট মুদ্রা পাওয়া যাবে।\n3. লেভেল পরিষ্কার করার পর, সেই লেভেলের জন্য 「রিভিজিট「 ফাংশন আনলক হবে। নোট: 「রিভিজিট「 ফাংশন ব্যবহার করলে অ্যাফিনিটি পাওয়া যাবে না।\n4. আপনি অ্যালুমনি সহায়তা ব্যবহার করে লেভেলগুলো আরও সহজে পরিষ্কার করতে পারবেন।\n\n<Title:ইভেন্ট বোনাস>\n1. নির্দিষ্ট অ্যাওয়েকনার বা নিয়তিচক্রের মালিকানা (মোতায়েন করা আবশ্যক নয়) থাকলে 「উইচের দোকান「 কোয়েস্ট পুরস্কারে 「বিবর্ণ পশুর খুলি「, 「ছায়াময় পশুর খুলি「 এবং 「রক্তিম পশু খুলি「-র অতিরিক্ত ড্রপ বোনাস (রিভিজিটসহ) পাওয়া যাবে। নির্দিষ্ট বোনাসগুলো নিম্নরূপ:\nঅ্যাওয়েকনার 「ড্যাফোডিল「: এনলাইটেন 0/1/2/3 বা তার বেশি, বোনাস: 20%/30%/40%/50%\nSSR নিয়তিচক্র 「মোস্ট প্রেশাস কালেকশন「: স্ট্যাক পজিশন 0/1/2/3 বা তার বেশি, বোনাস: 20%/30%/40%/50%\nSR নিয়তিচক্র 「জাদুকরীর চওড়া কানার টুপি「: স্ট্যাক পজিশন 0/1/2/3 বা তার বেশি, বোনাস: 20%/30%/40%/50%\n2. ভিন্ন অ্যাওয়েকনার বা নিয়তিচক্র থেকে প্রাপ্ত 「ইভেন্ট বোনাস「 সমষ্টিগতভাবে গণনা করা হয়।\n3. বিশেষভাবে, উন্মাদনা কঠিনতায় চ্যালেঞ্জের প্রথমবার পরিষ্কার করার পুরস্কার 「ইভেন্ট বোনাস「 দ্বারা প্রভাবিত হবে না।\n\n<Title:উইচের ভাণ্ডার>\n1. মোট তিনটি 「উইচের ভাণ্ডার「 রয়েছে, যেগুলো নিম্নলিখিত সময়ে খুলবে:\n「সোলেসের আনন্দ「: 24 ফেব্রুয়ারি 9:00 ~ 17 মার্চ 9:00।\n「গ্র্যান্ডিওস সিক্রেটস「: 26 ফেব্রুয়ারি 9:00 ~ 17 মার্চ 9:00।\n「ট্রেজার্ড ওয়্যারস「: 28 ফেব্রুয়ারি 9:00 ~ 17 মার্চ 9:00।\n2. প্রতিটি বিনিময়ে 750টি 「বিবর্ণ পশুর খুলি「/「ছায়াময় পশুর খুলি「/「রক্তিম পশু খুলি「 খরচ হবে, এবং ভাণ্ডার থেকে পাঁচটি আইটেম পুরস্কারের মধ্যে এলোমেলোভাবে একটি পাওয়া যাবে।\n3. প্রতিটি ভাণ্ডারের আইটেম পুরস্কার 「বিশেষ সামগ্রী「 এবং 「সাধারণ সামগ্রী「-তে বিভক্ত, এবং রিসেট করলে নির্দিষ্ট আইটেম পুরস্কারের অবশিষ্ট পরিমাণ সীমা পর্যন্ত পুনরায় সেট করা যায়। নির্দিষ্ট নিয়মাবলি হলো:\n(1) প্রথম 2 বার রিসেটের ক্ষেত্রে: 「বিশেষ সামগ্রী「-র কোনো অবশিষ্ট পরিমাণ না থাকলে, কিপাররা রিসেট বেছে নিতে পারেন, যা 「বিশেষ সামগ্রী「 এবং 「সাধারণ সামগ্রী「 উভয়ের অবশিষ্ট পরিমাণই সীমা পর্যন্ত পুনরুদ্ধার করবে; তারা চাইলে বিনিময় চালিয়ে যেতে পারেন। যখন 「সাধারণ সামগ্রী「-রও কোনো অবশিষ্ট পরিমাণ থাকবে না, তখন বিনিময় চালিয়ে যেতে রিসেট করা আবশ্যক।\n(2) 3য় রিসেট থেকে: কেবল তখনই রিসেট করা যাবে যখন 「সাধারণ সামগ্রী「-র কোনো অবশিষ্ট পরিমাণ থাকবে না, এবং এটি 「সাধারণ সামগ্রী「-র অবশিষ্ট পরিমাণকে সীমা পর্যন্ত পুনরুদ্ধার করবে; 「বিশেষ সামগ্রী「 আর রিসেট হবে না।\n\n<Title:স্পেশাল ডিসপ্যাচ রেকর্ড>\n1. ইভেন্ট চলাকালীন, 「স্পেশাল ডিসপ্যাচ রেকর্ড: বৃষ্টিভেজা শহরের ছায়া「 বিনামূল্যে উন্মুক্ত থাকবে।\n2. ইভেন্ট শেষ হওয়ার পরও 「স্পেশাল ডিসপ্যাচ রেকর্ড: বৃষ্টিভেজা শহরের ছায়া「-এর তদন্ত অগ্রগতি সংরক্ষিত থাকবে। ইভেন্ট চলাকালীন আনলক না করা থাকলে, ইভেন্ট-পরবর্তী সময়ে 「রিয়েলিটি ভার্জ「*7 ব্যয় করে এটি আনলক করা যাবে।\n3. ইভেন্ট চলাকালীন হোক বা না হোক, 「স্পেশাল ডিসপ্যাচ রেকর্ড: বৃষ্টিভেজা শহরের ছায়া「 পরিষ্কার করলে সবসময়ই 「পসি: কুয়াশার প্রকৃত রূপ「 পুরস্কার হিসেবে পাওয়া যাবে।"
