  Activity_70438_ActivityName = {
    Text = "উজ্জাহ বিড়ালের বিধি"
  },
  Activity_70438_ActivityPlot = {
    Text = "প্রার্থনা উৎসব ঘনিয়ে আসছে, সবাই উদযাপনের প্রস্তুতিতে ব্যস্ত, কেউ লক্ষ্যই করেনি যে কোণায় কালো রঙের দলা নীরবে নড়াচড়া করছে — ক্ষুদ্র বন্দী তরলে রূপ নিয়ে খাঁচা থেকে পালিয়ে গেছে।\nমাত্রার ফাটল জ্বলে উঠতেই কালো লোমগোলা বিভক্ত হতে শুরু করল......কালো বিড়ালের ঢেউ গোটা ক্যাম্পাসকে গ্রাস করছে!\nতুমি এটা উপেক্ষা করে স্কুল প্রশাসনের হাতে এই উদ্ভট ঘটনা ছেড়ে দিতে চেয়েছিলে।\nকিন্তু ওরা সিলভার কোর আর গোল্ড ভাউচার ফেলে — এটা ভেবে তুমি মত বদলালে।"
