    Text = "ভিন্নজগৎ যাত্রাপঞ্জি"
  },
  Activity_76217_ActivityTips = {
    Text = "ইভেন্টের নিয়ম：\n1、গোপনরক্ষক নির্দিষ্ট যাত্রাপঞ্জি মিশন সম্পন্ন করার পর, 「ভিন্নজগৎ যাত্রাপঞ্জি」-তে পুরস্কার সংগ্রহ করতে পারবেন।\n2、「ভিন্নজগৎ যাত্রাপঞ্জি」স্থায়ীভাবে উন্মুক্ত।\n3、「প্রিমিয়াম যাত্রাপঞ্জি」আনলক করার পর, মিশন সম্পন্ন করলে অতিরিক্ত পুরস্কার সংগ্রহ করা যাবে।\n4、দয়া করে মনে রাখবেন: এই ইভেন্টে আনলক করা 「প্রিমিয়াম যাত্রাপঞ্জি」শুধুমাত্র এই ইভেন্টেই কার্যকর। গোপনরক্ষকদের বিবেচনামূলক ও যুক্তিসঙ্গত খরচ করার অনুরোধ করা হচ্ছে।"
  },
