  },
  Activity_78652_ActivityPlot = {
    Text = "হিস্টিরিয়া। কেউ বলে ম্যানিয়া, কেউ বলে মনের ভাঙন; এই যুগে এই রোগ নির্ণয় মানেই মৃত্যুদণ্ড। সৌভাগ্যবশত, মিথ্যাগের বিজ্ঞানী ও অনুসন্ধান কর্মকর্তারা নিজেদের এক বিশেষ উন্মাদনায় আক্রান্ত: তারা এই সন্ত্রাসকে জয় করতেই বদ্ধপরিকর।"
