  Activity_78722_ActivityTips = {
    Text = "<Title: অন্ধকার স্রোতের পতঙ্গধ্বনি·সময়সীমিত প্রি-অর্ডার>\n·এই সময়সীমিত প্রি-অর্ডার ইভেন্টে 8টি গিফট প্যাক রয়েছে, যার মধ্যে প্রথম গিফট প্যাকটি সরাসরি বিনামূল্যে সংগ্রহ করা যাবে, 2-8 নম্বর গিফট প্যাক সংগ্রহ করতে「অন্ধকার স্রোতের পতঙ্গধ্বনি·সময়সীমিত প্রি-অর্ডার」ক্রয় করতে হবে।\n·「অন্ধকার স্রোতের পতঙ্গধ্বনি·সময়সীমিত প্রি-অর্ডার」ক্রয়ের পর অবিলম্বে 2 নম্বর গিফট প্যাকের পুরস্কার সংগ্রহ করা যাবে; পরবর্তী গিফট প্যাকগুলো সংগ্রহ করতে নির্দিষ্ট সময় অপেক্ষা করতে হবে।\n·「অন্ধকার স্রোতের পতঙ্গধ্বনি·সময়সীমিত প্রি-অর্ডার」ক্রয়ের সময়সীমা রয়েছে, মেয়াদ উত্তীর্ণ হলে আর ক্রয় করা যাবে না। অনুগ্রহ করে গোপনরক্ষক 7 এপ্রিল 9:00-এর আগে বিবেচনা করে ক্রয় করুন।"
