  },
  Activity_78752_ActivityTips = {
    Text = "<Title:কার্যক্রমের নিয়মাবলী>\n·「অস্থায়ী টেক্সট」কার্যক্রম চলাকালীন, রক্ষকরা মুশিং·টিংকেট সহ সিস্টেম প্রিসেট দল ব্যবহার করে নির্দিষ্ট স্তরগুলি অসীমবার অভিজ্ঞতা নিতে পারবেন।\n·কার্যক্রমের স্তর অভিজ্ঞতা নেওয়ার সময়, দল গঠনে জাগরণকারী পরিবর্তন করা যাবে না।\n<Title:কার্যক্রমের পুরস্কার>\n·প্রথমবার স্তরের চ্যালেঞ্জ সম্পন্ন করার পর, কার্যক্রম ইন্টারফেসে ট্রায়াল পুরস্কার সংগ্রহ করা যাবে।"
