  Activity_80312_ActivityName = {
    Text = "পুনর্বাসন যাত্রাপঞ্জি"
  },
  Activity_80312_ActivityTips = {
    Text = "ইভেন্টের নিয়ম：\n1、গোপনরক্ষক নির্দিষ্ট যাত্রাপঞ্জি মিশন সম্পন্ন করার পর, 「পুনর্বাসন যাত্রাপঞ্জি」-তে পুরস্কার সংগ্রহ করতে পারবেন।\n2、「পুনর্বাসন যাত্রাপঞ্জি」স্থায়ীভাবে উন্মুক্ত।\n3、「প্রিমিয়াম যাত্রাপঞ্জি」আনলক করার পর, মিশন সম্পন্ন করলে অতিরিক্ত পুরস্কার সংগ্রহ করা যাবে।\n4、দয়া করে মনে রাখবেন: এই ইভেন্টে আনলক করা 「প্রিমিয়াম যাত্রাপঞ্জি」শুধুমাত্র এই ইভেন্টেই কার্যকর। গোপনরক্ষকদের বিবেচনামূলক ও যুক্তিসঙ্গত খরচ করার অনুরোধ করা হচ্ছে।"
  },
  Activity_81019_ActivityName = {
    Text = "ঝাড়ু ও বিস্ময়"
  },
  Activity_81019_ActivityPlot = {
    Text = "কে স্বপ্নময় কাদাথে ঘুরে বেড়ায়, মালিকের জন্য আবর্জনা পরিষ্কার করে?\nসে গ্যালেন~সে গ্যালেন!\nক্ষয় পরিষ্কার~স্বপ্নে বায়ু চলাচল~মাত্রা জীবাণুমুক্তকরণ~সবকিছু ঝকঝকে করে তোলা~\nসর্বোপরি পরিষ্কার-পরিচ্ছন্নতায়, গ্যালেন কিন্তু পেশাদার!\nমালিক কি চেষ্টা করতে চান! গ্যালেন পরিষ্কারের সমস্ত কৌশল, কিছুই গোপন না রেখে মালিককে শেখাবে!"
  },
  Activity_81019_ActivityTips = {
    Text = "<Title:ইভেন্ট পরিচিতি>\n1、ইভেন্ট চলাকালীন, কিপার অফ সিক্রেটস 「পরিষ্কার অগ্রগতি」-তে অংশগ্রহণ করে 「পরিষ্কারের সরঞ্জাম」 সংগ্রহ করতে পারবেন।\n2、「পরিষ্কারের সরঞ্জাম」 নির্দিষ্ট পরিমাণে জমা হলে 「ধুলো পরিষ্কারের ভাতা」 থেকে সমৃদ্ধ পুরস্কার পাওয়া যাবে, যার মধ্যে রয়েছে ইভেন্ট সীমিত অবতার 「ক্লিনিং মাস্টার」, সিলভার কোর, প্রিস্টিন কোর, উইজডম স্টোন ফ্র্যাগমেন্ট ইত্যাদি।\n\n<Title: পরিষ্কার অগ্রগতি>\n1、「পরিষ্কার অগ্রগতি」-তে বিভিন্ন ধরনের পরিষ্কারের মিশন রয়েছে, কিপার অফ সিক্রেটস পরিষ্কারের মিশন সম্পন্ন করে 「পরিষ্কারের সরঞ্জাম」 সংগ্রহ করতে পারবেন। প্রতিদিন সব ধরনের পরিষ্কারের মিশন সম্পন্ন করলে একটি অতিরিক্ত পুরস্কারও পাওয়া যাবে!\n2、ইভেন্ট চলাকালীন, প্রথমবার প্রতিটি ধরনের পরিষ্কারের মিশন সম্পন্ন করলে একটি লুকানো গল্প চালু হবে।\n3、「পরিষ্কার অগ্রগতি」 ইভেন্ট চলাকালীন প্রতিদিন সকাল 9:00(GMT+8)-এ রিফ্রেশ ও রিসেট হবে।\n\n<Title: ধুলো পরিষ্কারের ভাতা>\n1、কিপার অফ সিক্রেটস 「পরিষ্কারের সরঞ্জাম」 জমা করে সংশ্লিষ্ট পুরস্কার সংগ্রহ করতে পারবেন। প্রতি 1000 「পরিষ্কারের সরঞ্জাম」 পৌঁছালে সমৃদ্ধ সম্পদ পুরস্কার পাওয়া যাবে, মোট 10000 「পরিষ্কারের সরঞ্জাম」 পৌঁছালে পরিষ্কার অভিযানের এক্সক্লুসিভ অবতার 「ক্লিনিং মাস্টার」 পাওয়া যাবে।\n\n<Title:গ্যালেনের উপহার>\nইভেন্ট চলাকালীন, 「গ্যালেনের উপহার」-এ সাইন ইন করে গ্যালেন কিপার অফ সিক্রেটসদের জন্য যে উপহার প্রস্তুত করেছেন তা সংগ্রহ করতে পারবেন!\n\n<Title:ইভেন্টের সময়>\nএই ইভেন্টটি শুধুমাত্র 28 এপ্রিল সকাল 9:00 - 12 মে সকাল 9:00(GMT+8) পর্যন্ত উন্মুক্ত থাকবে। 12 মে সকাল 9:00(GMT+8)-এর পর ইভেন্ট শেষ হয়ে যাবে, সকল কিপার অফ সিক্রেটস অনুগ্রহ করে 「ধুলো পরিষ্কারের ভাতা」-র পুরস্কার সংগ্রহ করতে ভুলবেন না!"
  },
