  Activity_81178_ActivityPlot = {
    Text = "ধূসর আকাশ থেকে তীব্র বৃষ্টি তির্যকভাবে ঝরে পড়ছে, সমুদ্রের বুকে ঝপঝপ শব্দ তুলছে।\nনির্দয় বজ্রপাত উন্মত্তভাবে গর্জে উঠছে, সমুদ্রের তলদেশে লুকিয়ে থাকা অসীম আতঙ্কের আগমন ঘোষণা করছে।\nমহিমান্বিত নটিলাস যেন হামাগুড়ি দেওয়া এক শিশুর মতো, উত্তাল ঢেউয়ের মাঝে ভঙ্গুরভাবে দুলছে।\nকেউ জানে না তার ভাগ্যে কী লেখা আছে, ঠিক যেমন খামখেয়ালি সমুদ্র যখন তার ক্রোধ প্রদর্শন করে, তখনই মানুষ বুঝতে পারে সে কতটা তুচ্ছ।"
