    Text = "পবিত্র রাজ্যের ছায়ায় উঁকি"
  },
  Activity_81771_ActivityPlot = {
    Text = "কেউ কখনো দেব-রিয়েল্মের পবিত্র জ্যোতি দেখেনি, কিন্তু আকস্মিকভাবে ফাঁস হয়ে যাওয়া সত্যের টুকরো থেকে মানুষ দেব-রিয়েল্মের ছায়া অনুভব করতে পারে।\nওটা আছে, সেখানেই আছে, সর্বদা আছে, আর অসংখ্য নিবেদিত বিশ্বাসী তাকে সত্যিই অবতীর্ণ করবে।\nযে মূল্যেই হোক, যত ভয়াবহ পাপই হোক না কেন, তার বিনিময়ে।"
