  Activity_84175_ActivityTips = {
    Text = "ইভেন্টের নিয়মাবলি:\n১. নির্ধারিত কাজ সম্পন্ন করলে পুনরাবৃত্ত সংকলনে পুরস্কার সংগ্রহ করুন।\n২. কাজগুলোকে বিভিন্ন দলে ভাগ করা হয়েছে; ইভেন্ট শুরু হওয়ার পর প্রতিদিন একটি করে দল আনলক হবে।\n৩. তীর্থযাত্রা সংকলন আনলক করলে কাজ সম্পন্নের জন্য অতিরিক্ত পুরস্কার পাওয়া যাবে।\n৪. দ্রষ্টব্য: সক্রিয় করা তীর্থযাত্রা সংকলন কেবলমাত্র এই একটিমাত্র সংকলন ইভেন্টেই কার্যকর থাকবে।"
  },
  Activity_84176_ActivityName = {
    Text = "ঊরোবোরোস কোডেক্স"
  },
  Activity_84176_ActivityTips = {
    Text = "ইভেন্টের নিয়মাবলি:\n১. নির্ধারিত কাজ সম্পন্ন করলে ঊরোবোরোস কোডেক্স থেকে পুরস্কার সংগ্রহ করুন।\n২. কাজগুলো বিভিন্ন দলে বিভক্ত থাকবে, এবং ইভেন্ট শুরু হওয়ার পর প্রতিদিন একটি করে দল আনলক হবে।\n৩. প্রিমিয়াম আর্কাইভস আনলক করলে কাজ সম্পন্নের জন্য অতিরিক্ত পুরস্কার পাওয়া যাবে।\n৪. দ্রষ্টব্য: সক্রিয় করা প্রিমিয়াম আর্কাইভস কেবল এই একটিমাত্র আর্কাইভস ইভেন্টেই কার্যকর থাকবে।"
  },
  Activity_89008_ActivityName = {
    Text = "আবর্তিত মাত্রার অনুসরণ"
  },
  Activity_89008_ActivityPlot = {
    Text = "সে অসংখ্য মাত্রা, অসংখ্য জগৎ পেরিয়ে এসেছে, অসংখ্য আশা ও হতাশার মধ্য দিয়ে গেছে, কিন্তু সে থামবে না। কারণ, সে স্পষ্ট জানে তার গন্তব্য কোথায়—যেখানে তুমি আছ।"
  },
  Activity_89008_ActivityTips = {
    Text = "<Title:পরিচিতি>\n1। ইভেন্ট চলাকালীন, গোপনরক্ষক প্রতিদিন লগইন করার পর 「আবর্তিত মাত্রার অনুসরণ」 থেকে দৈনিক সাইন-ইন পুরস্কার সংগ্রহ করতে পারবেন।\n2। পুরস্কার গোপনরক্ষকের মোট লগইনের ভিত্তিতে ক্রমানুসারে আনলক হবে, দৈনিক সাইন-ইন পুরস্কার সকাল 9টায়(GMT+8) রিফ্রেশ হবে।\n\n<Title:সীমিত সময়ের মিশন>\n·ইভেন্ট চলাকালীন, মোট 7 দিন লগইন করলে সীমিত সময়ের মিশন সম্পন্ন হবে এবং 「সাধারণ ইলিউশন পোশাক ডিজাইন ভাউচার(প্রথম পর্ব)」 ×1 পাবেন!\n·26 মে সকাল 9:00 - 9 জুন সকাল 9:00(GMT+8) সময়কালে, 「দোকান: ইলিউশন পোশাক অর্ডার」-এ 「সাধারণ ইলিউশন পোশাক ডিজাইন ভাউচার(প্রথম পর্ব)」 ব্যবহার করে সাধারণ ইলিউশন পোশাক বিনিময় করা যাবে।\n·「সাধারণ ইলিউশন পোশাক ডিজাইন ভাউচার(প্রথম পর্ব)」 পাওয়ার আরও উপায় কমিউনিটি ও বিজ্ঞপ্তিতে জানতে পারবেন।"
  },
  Activity_89008_BannerText = {
