  Activity_89576_ActivityPlot = {
    Text = "প্রতিদিন লগইন করে স্মারক সীমিত SSR ভাগ্যচক্র 「ধ্বংসভূমিতে পুনর্জন্ম」 সংগ্রহ করুন, মোট 16টি সংগ্রহ করা যাবে!"
  },
  Activity_89576_ActivityTips = {
    Text = "<Title:পরিচিতি>\nবিশ্ব ধ্বংস হচ্ছে। এমন বিশ্বে, হতাশা স্বাভাবিক, যন্ত্রণা স্বাভাবিক। আমাকে অভ্যস্ত হতে হবে। কিন্তু... এখনও উষ্ণতা আমার হৃদয়ে সুপ্ত হয়ে আছে, বেরিয়ে আসার অপেক্ষায়।\n\n<Title:ইভেন্টের নিয়ম>\n·ইভেন্ট চলাকালীন, গোপনরক্ষক প্রতিদিন লগইন করার পর 「আশা যেন আবার অঙ্কুরিত হোক」 থেকে স্মারক সীমিত SSR ভাগ্যচক্র 「ধ্বংসভূমিতে পুনর্জন্ম」 সংগ্রহ করতে পারবেন, মোট 16 বার সংগ্রহ করা যাবে।\n·পুরস্কার গোপনরক্ষকের মোট লগইনের ভিত্তিতে ক্রমানুসারে আনলক হবে, দৈনিক লগইন পুরস্কার সকাল 9টায়(GMT+8) রিফ্রেশ হবে।"
  },
