  Activity_89899_ActivityTips = {
    Text = "<Title:কার্যক্রমের সারসংক্ষেপ>\n1. কার্যক্রম চলাকালে, রক্ষকরা 「মায়াবী একচশমা」 ব্যবহার করে স্কিন আহ্বান করতে পারবেন। প্রতিটি আহ্বানের জন্য প্রয়োজনীয় 「মায়াবী একচশমা」‑র পরিমাণ ক্রমশ বৃদ্ধি পাবে।\n2. 5ম প্রচেষ্টা থেকে প্রিমিয়াম স্কিন পাওয়ার সম্ভাবনা উন্মুক্ত হবে। 10 বার আহ্বান সম্পন্ন করলে বর্তমান প্রিমিয়াম স্কিন নিশ্চিতভাবে প্রাপ্ত হবে।\n3. কার্যক্রম শেষ হওয়ার পর অবশিষ্ট থাকা সব 「মায়াবী একচশমা」 স্বয়ংক্রিয়ভাবে সিলভার প্রাইম‑এ রূপান্তরিত হবে।"
