  Activity_90052_ActivityTips = {
    Text = "<Title:ইভেন্টের নিয়ম>\n·「ক্ষয়িত মস্তিষ্ক」ইভেন্ট চলাকালীন, সিক্রেটকিপার 「মেল্টডাউন·ডোর」সহ সিস্টেম প্রিসেট দল ব্যবহার করে নির্দিষ্ট স্টেজ সীমাহীনবার অভিজ্ঞতা করতে পারবেন।\n·ইভেন্ট স্টেজ অভিজ্ঞতার সময়, দলের অ্যাওয়েকেনড সদস্য পরিবর্তন করা যাবে না।\n<Title:ইভেন্ট পুরস্কার>\n·প্রথমবার স্টেজ চ্যালেঞ্জ সম্পন্ন করার পর, ইভেন্ট ইন্টারফেসে ট্রায়াল পুরস্কার সংগ্রহ করা যাবে।"
  },
  Activity_90493_ActivityName = {
    Text = "বাস্তব যুদ্ধ প্রশিক্ষণ"
  },
  Activity_90493_ActivityTips = {
    Text = "ইভেন্ট নিয়মাবলী：\n1、কিপার সংশ্লিষ্ট স্টেজে যুদ্ধ সম্পর্কিত বিষয়বস্তু শিখতে এবং অনুশীলন করতে পারবেন।\n2、কিপার সংশ্লিষ্ট প্র্যাকটিক্যাল ট্রেনিং স্টেজ ক্লিয়ার করলে, 「প্র্যাকটিক্যাল ট্রেনিং」 থেকে পুরস্কার সংগ্রহ করতে পারবেন।"
