  Activity_90861_ActivityTips = {
    Text = "<Title:সংযুক্ত নিয়তি>\nএই সীমিত আর্কাইভস-এ রয়েছে 8টি উপহারের প্যাক। প্রথম উপহারের প্যাকটি সরাসরি বিনামূল্যে সংগ্রহ করা যাবে, তবে 2–8 নম্বর উপহারের প্যাক সংগ্রহের আগে অবশ্যই 「সংযুক্ত নিয়তি」 ক্রয় করতে হবে।\n「সংযুক্ত নিয়তি」 ক্রয় করার পর, 2য় উপহারের প্যাকের পুরস্কার তাৎক্ষণিকভাবে সংগ্রহ করা যাবে; পরবর্তী প্রতিটি উপহারের প্যাক সংগ্রহের আগে নির্দিষ্ট সময় পর্যন্ত প্রতীক্ষা করতে হবে।\n20 এপ্রিল সকাল 9:00-র আগে 「সংযুক্ত নিয়তি」 ক্রয় করলে অতিরিক্ত পুরস্কারও মিলবে: এক্সক্লুসিভ অবতার 「মোইরাই উইভার」 এবং 「নিরাকারের আমন্ত্রণপত্র」 ×10! 20 এপ্রিল সকাল 9:00-র পর ক্রয় করলে আর এই সীমিত সময়ের এক্সক্লুসিভ পুরস্কারগুলি পাওয়া যাবে না।\nক্রয়ের পর, এই সীমিত আর্কাইভস-এর স্থায়িত্ব স্থায়ী হয়ে যাবে, এবং সব উপহারের প্যাক সংগ্রহের পরের দিন ইভেন্টটি বন্ধ হবে।\n「সংযুক্ত নিয়তি」 18 মে সকাল 9:00 পর্যন্ত ক্রয়ের জন্য সংগ্রহযোগ্য থাকবে।"
