  Activity_90862_ActivityTips = {
    Text = "<Title: অস্থায়ী টেক্সট>\n·এই সীমিত সময়ের প্রি-অর্ডার ইভেন্টে 8টি গিফট প্যাক রয়েছে, যার মধ্যে প্রথম গিফট প্যাকটি সরাসরি বিনামূল্যে সংগ্রহ করা যাবে, 2-8 নম্বর গিফট প্যাক সংগ্রহ করতে 「অস্থায়ী টেক্সট」 কিনতে হবে।\n·「অস্থায়ী টেক্সট」 কেনার পর অবিলম্বে 2য় গিফট প্যাকের পুরস্কার সংগ্রহ করা যাবে; পরবর্তী গিফট প্যাকগুলো সংগ্রহ করতে নির্দিষ্ট সময় অপেক্ষা করতে হবে।\n·「অস্থায়ী টেক্সট」 কেনার সময়সীমা রয়েছে, মেয়াদ উত্তীর্ণ হলে আর কেনা যাবে না। অনুগ্রহ করে গোপনরক্ষক 7 এপ্রিল সকাল 9:00(GMT+8) এর আগে বিবেচনা করে কিনুন।"
