  Activity_90865_ActivityTips = {
    Text = "<Title:অতল গর্ভসঞ্চার: সীমিত আর্কাইভস>\nএই সীমিত আর্কাইভসে রয়েছে 8টি উপহার প্যাক। প্রথম প্যাকটি বিনামূল্যে সংগ্রহযোগ্য।\n2 থেকে 8 নম্বর প্যাক সংগ্রহ করতে 「অতল গর্ভসঞ্চার: সীমিত আর্কাইভস」 ক্রয় করা আবশ্যক।\nএকবার ক্রয় সম্পন্ন হলে, তুমি সঙ্গে সঙ্গেই 2য় প্যাক সংগ্রহ করতে পারবে। বাকি প্যাকগুলো নির্দিষ্ট অপেক্ষাকালের পর সংগ্রহ করা যাবে।\nবিশেষ বোনাস হিসেবে, 17 নভেম্বর সকাল 9টার আগে ক্রয় করলে 「গভীর সাগরের শোকগাথা」 অবতার এবং 10টি 「নিরাকারের আমন্ত্রণপত্র」 পাবে। নির্ধারিত সময়সীমা পেরিয়ে গেলে এই অফার আর কার্যকর থাকবে না।\nদয়া করে লক্ষ্য করো: 「অতল গর্ভসঞ্চার: সীমিত আর্কাইভস」 নিজেই সীমিত সময়ের জন্য সংগ্রহযোগ্য, এবং 15 ডিসেম্বর সকাল 9টার পর আর ক্রয় করা যাবে না।"
