  Activity_94859_ActivityTips = {
    Text = "ইভেন্টের নিয়মাবলী：\n1、সিক্রেটকিপার নির্ধারিত ভ্রমণকথা মিশন সম্পন্ন করার পর, 「গ্রীষ্মকালীন ভ্রমণকথা」-তে পুরস্কার সংগ্রহ করতে পারবেন।\n2、「প্রিমিয়াম ভ্রমণকথা」আনলক করার পর, মিশন সম্পন্ন করলে অতিরিক্ত পুরস্কার সংগ্রহ করা যাবে।\n3、এবারের 「প্রিমিয়াম ভ্রমণকথা」ক্রয়ের সময়সীমা আছে, মেয়াদ উত্তীর্ণ হলে আর কেনা যাবে না। সিক্রেটকিপার অনুগ্রহ করে 10 অক্টোবর 6 তারিখ 9:00-এর আগে বিবেচনা করে কিনুন।\n4、অনুগ্রহ করে মনে রাখবেন: এই ইভেন্টে আনলক করা 「প্রিমিয়াম ভ্রমণকথা」শুধুমাত্র এই ইভেন্টে কার্যকর। সিক্রেটকিপার অনুগ্রহ করে বিবেচনা করে যুক্তিসঙ্গতভাবে খরচ করুন।"
