  Activity_96617_ActivityTips = {
    Text = "<Title:ইভেন্ট নিয়মাবলী>\n1、গোপনরক্ষক নির্ধারিত যাত্রাপথ মিশন সম্পন্ন করার পর,「ম্যাপেল লালিমা」-তে পুরস্কার সংগ্রহ করতে পারবেন।\n2、「ম্যাপেল লালিমা」23 মার্চ 9:00 (GMT+8)-এ শেষ হবে।\n3、「প্রিমিয়াম যাত্রাপথ」আনলক করার পর, মিশন সম্পন্ন করলে অতিরিক্ত পুরস্কার সংগ্রহ করা যাবে।\n4、অনুগ্রহ করে মনে রাখবেন: এই ইভেন্টে আনলক করা「প্রিমিয়াম যাত্রাপথ」শুধুমাত্র এই ইভেন্টে কার্যকর। অনুগ্রহ করে গোপনরক্ষক বিবেচনা করে যুক্তিসঙ্গতভাবে ব্যয় করুন।"
