  Activity_97853_ActivityPlot = {
    Text = "তুমি কি কখনও কল্পনা করেছ, যদি বিপর্যয় কখনও নেমে না আসত, তবে সকলে’র জীবন কেমন হতো?\nতোমার যে শক্তি বিশ্বকে রক্ষা করতে পারে, তার আর ব্যবহারের কোনো স্থান থাকত না; প্রতিদিন তুমি ছুটে বেড়াতে একঘেয়ে ক্যাম্পাস জীবনের পেছনে, আর সামান্য কিছু ক্রেডিট জোগাড়ের জন্য। খেলার মাঠ আর যুদ্ধ-প্রশিক্ষণে মগ্ন অবয়বে ভরা নয়; সেখানে এখন সারি সারি ক্যানভাসের তাঁবু, ক্লাব কার্যকলাপের জন্য, সাথে ভেসে আসে সদস্য সংগ্রহের ডাক আর দুষ্টু হাসিঠাট্টার শব্দ। স্কুলের ঘণ্টা বাজতেই ক্ষুধার্ত ছাত্ররা মুহূর্তে ভরে ফেলে ক্যাফেটেরিয়া...\nযদি তুমি যাদের যত্ন করো, তাদের দরজায় গিয়ে কড়া নাড়ো, কেমন হাসিমাখা মুখগুলো তোমার সামনে ভেসে উঠবে?"
